(function(){
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(w,origin)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const Q=(id,senseId,errorType,prompt,answer,d1,d2,explain)=>({id,senseId,type:'辨義與用法',errorType,prompt,options:[answer,d1,d2],answer,explain});
const P=(w,origin,contexts,mistakes,quiz)=>D(w,{etymology:E(w,origin),contexts,mistakes,quiz});
P('underrate','Formed from under- “too little” + rate, ultimately from Latin rata, “fixed or reckoned.”',[C('underrate.s1','评价','The review underrates the novel by focusing on its slow opening and ignoring the vivid final chapters.','這篇評論只著眼於小說緩慢的開頭，忽略生動的結尾章節，因此低估了它。','underrate + person / work / ability','Transitive verb: judge quality or importance as lower than it really is.','The reviewer gives the novel too little credit.'),C('underrate.s2','估值','The insurer may underrate the damaged painting if it uses the old appraisal.','如果保險公司採用舊估價，可能會把受損畫作估得過低。','underrate the value / cost of + noun','Transitive verb: assign a value below the true amount.','The old appraisal understates the painting’s current value.')],[M('The report underrates the bridge at $40 million, although its replacement value is only $25 million.','The report overrates the bridge at $40 million, although its replacement value is only $25 million.','Calling a value above the true amount is overrate; underrate means set it too low.','word-choice')],[Q('underrate.q1','underrate.s1','meaning','What does the review do when it underrates the novel?','It judges the novel as worse or less important than it is.','It praises the novel beyond what it deserves.','It calculates the novel’s printing cost.','The quality sense means give too low a judgment.'),Q('underrate.q2','underrate.s2','context','Why might an insurer underrate a painting?','It assigns a value below the painting’s true worth.','It insures the painting for more than any estimate.','It paints over the damage.','The valuation sense concerns setting the amount too low.'),Q('underrate.q3','underrate.s1','distinction','Which action underrates a speaker?','A judge dismisses strong evidence of the speaker’s skill.','A judge exaggerates the speaker’s talent.','A judge records the speaker’s age accurately.','Ignoring real skill gives too little credit.'),Q('underrate.q4','underrate.s2','word-choice','The house is worth $300,000, but the estimate says $220,000. What did it do?','It underrated the house.','It overrated the house.','It sold the house.','The estimate is below the real value.')]);
P('underscore','From under- + score, “a line drawn beneath writing”; the verb developed the sense “emphasize.”',[C('underscore.s1','强调','The final paragraph underscores why the safety rule applies even during short repairs.','最後一段強調了為何即使是短暫維修也須遵守安全規定。','underscore + point / need / importance','Transitive verb: emphasize a fact or idea.','The paragraph draws attention to the rule’s importance.'),C('underscore.s2','下划线','A single underscore separates the user name from the number in this file name.','這個檔名以一個底線分隔使用者名稱與數字。','an underscore between words / characters','Noun: the character _ used in writing or computing.','The mark is the low horizontal character.')],[M('Please underscore the account name by typing a space character: river_8.','Please insert an underscore in the account name: river_8.','An underscore is the low mark “_,” not a blank space.','word-choice')],[Q('underscore.q1','underscore.s1','meaning','What does the paragraph underscore?','It emphasizes the reason for following the rule.','It hides the rule from readers.','It draws a line beneath every sentence.','The verb means emphasize or make a point clear.'),Q('underscore.q2','underscore.s2','context','Which character is an underscore?','_','-','/','The underscore is the low horizontal mark.'),Q('underscore.q3','underscore.s1','distinction','Which sentence uses underscore as a verb?','The data underscore the need for a backup.','Type an underscore between the two words.','The underscore appears in the file name.','Here the evidence emphasizes a need.'),Q('underscore.q4','underscore.s2','grammar','Choose the natural phrase for the symbol _ in a username.','an underscore in the username','an underscore the username','a username underscored as a noun','The mark itself is a countable noun: an underscore.')]);
P('undersea','English compound of under + sea, describing a position or activity below the sea surface.',[C('undersea.s1','位置','An undersea ridge runs for hundreds of kilometres beneath the Pacific.','太平洋海面下有一道延伸數百公里的海底山脊。','an undersea + noun','Adjective: located or occurring below the sea’s surface.','The ridge lies below the ocean surface.'),C('undersea.s2','水下作业','The documentary follows an undersea survey carried out by a crewed research vessel.','這部紀錄片記錄了一艘載人研究船進行的水下勘測。','undersea survey / exploration / operation','Adjective: performed below the sea by divers or special equipment.','The survey is an activity conducted underwater.')],[M('The undersea ridge rose above the ocean and stood as a dry mountain on the beach.','The undersea ridge remained below the ocean surface.','Undersea describes something below the sea, not exposed on land.')],[Q('undersea.q1','undersea.s1','meaning','Where is an undersea ridge?','Below the surface of the sea.','On dry land above the water.','In the air above a ship.','The adjective places the ridge beneath the sea surface.'),Q('undersea.q2','undersea.s2','context','What makes the survey an undersea survey?','Researchers carry it out below the sea surface.','It studies clouds from a mountain.','It maps only the coastline from a road.','The activity takes place underwater.'),Q('undersea.q3','undersea.s1','distinction','Which object is undersea?','A cable laid along the ocean floor.','A flag flying above a harbour.','A boat stored on dry land.','The cable lies below the sea surface.'),Q('undersea.q4','undersea.s2','word-choice','Choose the phrase describing work by divers below water.','an undersea inspection','an overland inspection','an airborne inspection','The inspection is carried out under the sea.')]);
P('undershirt','Compound of under + shirt, named for the light garment worn beneath outer clothes.',[C('undershirt.s1','衣物','He wore a clean cotton undershirt beneath his work shirt on the cold morning.','寒冷的早晨，他在工作襯衫裡穿了一件乾淨的棉汗衫。','wear an undershirt under / beneath a shirt','Noun: a light shirt worn next to the skin under another garment.','The garment is an inner layer beneath his work shirt.')],[M('She put her undershirt over her coat so it would be the outermost layer.','She put her undershirt beneath her blouse as an inner layer.','An undershirt is worn under other clothes, not over a coat.')],[Q('undershirt.q1','undershirt.s1','meaning','Where is an undershirt normally worn?','Next to the skin under another shirt or garment.','Over a coat as outerwear.','Around the waist instead of trousers.','Its name and use describe an inner clothing layer.'),Q('undershirt.q2','undershirt.s1','context','Why did he wear an undershirt on a cold morning?','It added a light layer beneath his work shirt.','It replaced his work shirt as a coat.','It covered his shoes.','The garment is worn under outer clothing.'),Q('undershirt.q3','undershirt.s1','distinction','Which item is an undershirt?','A light top worn next to the body beneath a blouse.','A heavy coat worn over a jacket.','A belt worn around trousers.','The defining position is beneath other clothing.'),Q('undershirt.q4','undershirt.s1','word-choice','Choose the natural sentence.','He packed two undershirts for the trip.','He packed two undershirt for the trip.','He packed an undershirts for the trip.','A countable noun takes plural -s after the number two.','grammar')]);
P('underside','Formed from under + side, naming the lower or less visible face of an object.',[C('underside.s1','物体底面','Dust had collected on the underside of the desk where the cleaner could not reach.','灰塵積在清潔人員碰不到的桌子底面。','the underside of + object','Noun: the lower surface, often hidden from view.','The dust is on the desk’s bottom surface.'),C('underside.s2','生物结构','The butterfly’s underside is brown, unlike the bright blue upper side of its wings.','蝴蝶翅膀底面的褐色與上側亮藍色不同。','the underside of a leaf / wing / body','Noun: the lower side of an animal, leaf, or small object.','The reference is to the lower wing surface.')],[M('The underside of the table was its polished top, facing upward in the dining room.','The underside of the table was its lower surface, facing the floor.','The underside is the lower face, not the upward-facing top.')],[Q('underside.q1','underside.s1','meaning','Where is the underside of a desk?','On its lower surface, beneath the top.','On the top surface where books sit.','Inside a desk drawer.','Underside means the lower face of an object.'),Q('underside.q2','underside.s2','context','Which part of the butterfly has the brown pattern?','The lower surface of its wing.','The upper side of its wing.','The insect’s antenna only.','The context uses underside for the lower wing face.'),Q('underside.q3','underside.s1','distinction','Where would a repairer inspect a table’s underside?','On the bottom, below the tabletop.','On the polished top surface.','On the wall behind it.','The underside faces downward.'),Q('underside.q4','underside.s2','word-choice','Choose the correct phrase for a leaf’s lower face.','the underside of the leaf','the inside of the leaf’s stem','the outside above the leaf','Underside names the leaf’s lower surface.')]);
P('understand','From Old English understandan, whose earliest sense is uncertain; do not infer a literal modern “stand under” meaning.',[C('understand.s1','理解信息','After reading the wiring diagram twice, Nia understood how the alarm circuit worked.','妮婭把接線圖看了兩遍後，明白了警報電路的運作方式。','understand + idea / words / how-clause','Transitive verb: know the meaning or explanation of something.','She now knows how the circuit works.'),C('understand.s2','了解人或情況','His colleagues understand his silence as concentration rather than anger.','同事們把他的沉默理解為專注，而不是生氣。','understand + person / situation','Transitive verb: know a person or situation well.','They interpret his behaviour in context.'),C('understand.s3','體諒','I understand why the tenants objected to a rent increase after the heating failed.','暖氣故障後租金還要上漲，我理解房客為何反對。','understand why + person + verb','Transitive verb: accept why somebody feels or acts in a certain way.','The speaker recognizes the tenants’ reason as understandable.'),C('understand.s4','據悉','The bridge is understood to reopen once the engineers finish their tests.','據了解，工程師完成測試後橋梁就會重新開放。','be understood to + verb','Passive reporting use: believe or accept something based on information received.','This reports what people have been told, not firsthand certainty.')],[M('I understand the instructions, so I cannot explain what “turn off the main switch” means.','I understand the instructions, so I can explain what “turn off the main switch” means.','Understanding instructions means knowing their meaning well enough to explain them.')],[Q('understand.q1','understand.s1','meaning','What did Nia understand after studying the diagram?','How the alarm circuit worked.','Only the colour of the paper.','That the circuit had no parts.','Sense 1 is knowing the meaning or explanation.'),Q('understand.q2','understand.s2','context','How do the colleagues understand his silence?','They interpret it as concentration rather than anger.','They know he is speaking loudly.','They believe the heating has failed.','This sense is interpreting a person’s behaviour.'),Q('understand.q3','understand.s3','distinction','Which sentence expresses sympathy for someone’s reason?','I understand why the tenants are upset.','I understand the diagram’s symbols.','The bridge is understood to reopen.','The why-clause expresses accepting someone’s feelings or actions.'),Q('understand.q4','understand.s4','grammar','What does “The bridge is understood to reopen” report?','People believe or have been told it will reopen.','The speaker personally repaired it.','No one has any information about it.','The passive reporting phrase signals a reported belief.')]);
P('understandable','From understand + -able, “capable of being understood”; also applied to a comprehensible explanation.',[C('understandable.s1','可理解的反应','Her disappointment was understandable after the team cancelled the trip without warning.','團隊毫無預警取消行程後，她感到失望是可以理解的。','an understandable reaction / decision','Adjective: reasonable or easy to accept in the circumstances.','Given the cancellation, her response makes sense.'),C('understandable.s2','清楚易懂','The manual gives an understandable explanation of how to reset the router.','手冊清楚易懂地說明如何重設路由器。','an understandable explanation / account','Adjective: expressed clearly enough to be followed.','Readers can follow the explanation.')],[M('The manual was understandable because every instruction was unexplained and impossible to follow.','The manual was understandable because its instructions were clear and easy to follow.','Understandable writing can be followed; unexplained instructions make it difficult.')],[Q('understandable.q1','understandable.s1','meaning','Why was her disappointment understandable?','The team cancelled her trip without warning.','She had never planned to travel.','The team gave her a generous gift.','This sense means reasonable in the situation.'),Q('understandable.q2','understandable.s2','context','What makes the router manual understandable?','Its explanation is clear enough to follow.','It uses unexplained codes on every page.','It omits the reset instructions.','This sense concerns clarity of expression.'),Q('understandable.q3','understandable.s1','distinction','Which is an understandable reaction?','A student feels nervous before a difficult first exam.','A student feels no emotion after an ordinary lunch.','A machine gives a clear instruction.','The student’s nerves make sense in the circumstances.'),Q('understandable.q4','understandable.s2','word-choice','Choose the phrase praising clear writing.','an understandable set of directions','an unspoken set of directions','an unreadable set of directions','Understandable directions are clear enough to follow.')]);
P('understandably','From understandable + -ly, an adverb meaning “in a way that can be understood or accepted.”',[C('understandably.s1','合情合理','The passengers were understandably angry when the train stopped for three hours without an announcement.','列車停了三小時又沒有公告，乘客生氣是可以理解的。','understandably + emotion / response','Sentence adverb: in a way that is reasonable in the circumstances.','The delay explains why anger was a reasonable response.')],[M('The passengers were understandably angry, although the train arrived early and they had received clear updates.','The passengers were understandably angry after a long unexplained delay.','The adverb should introduce a response supported by the circumstances.')],[Q('understandably.q1','understandably.s1','meaning','Why were the passengers understandably angry?','They faced a long delay with no announcement.','The train arrived early with helpful updates.','They had already reached their destination.','The circumstances make their anger reasonable.'),Q('understandably.q2','understandably.s1','context','Which sentence uses understandably naturally?','Mina was understandably worried when the storm warning arrived.','Mina was understandably relaxed because nothing unusual happened.','Mina understandably is a worry storm warning.','A warning makes worry a reasonable response.'),Q('understandably.q3','understandably.s1','grammar','Where does understandably describe a reaction?','He understandably refused the unsafe assignment.','He understandable refused the unsafe assignment.','He refused understandable the unsafe assignment.','The -ly adverb modifies the verb phrase refused.'),Q('understandably.q4','understandably.s1','distinction','What does understandably signal in “She was understandably relieved”?','Her relief makes sense given the situation.','Her relief was impossible to explain.','She explained something in a simple style.','The adverb marks a reasonable emotional response.')]);
P('understanding','From understand + -ing; the noun developed senses of acquired knowledge and sympathetic insight.',[C('understanding.s1','知识掌握','The course gives trainees a basic understanding of how local elections are counted.','這門課讓學員初步了解地方選舉如何計票。','an understanding of + subject','Noun: knowledge acquired about a subject or process.','Trainees learn how the counting process works.'),C('understanding.s2','深入了解','Years of fieldwork gave the biologist a deep understanding of the wetland ecosystem.','多年的實地研究使這位生物學家深入了解濕地生態系統。','a deep / clear understanding of + person or problem','Noun: detailed insight into a person, problem, or how something works.','The knowledge is extensive and explanatory.')],[M('The course gave trainees an understanding of elections, but it taught them nothing about how votes are counted.','The course gave trainees an understanding of elections by explaining how votes are counted.','Understanding a subject requires knowledge of its relevant process or ideas.')],[Q('understanding.q1','understanding.s1','meaning','What understanding does the course provide?','Knowledge of how local election votes are counted.','A list of trainees’ home addresses.','The result of a wetland field study.','Sense 1 is knowledge about a subject or process.'),Q('understanding.q2','understanding.s2','context','Why does the biologist have a deep understanding of the wetland?','Years of fieldwork gave detailed insight into the ecosystem.','The biologist has never visited the wetland.','The course only explained election ballots.','Deep understanding means extensive insight.'),Q('understanding.q3','understanding.s1','distinction','Which phrase uses understanding as learned knowledge?','a basic understanding of tax rules','an understanding smile between old friends','an empathetic understanding of her grief','The tax phrase refers to acquired subject knowledge.'),Q('understanding.q4','understanding.s2','word-choice','Which phrase points to detailed insight into a difficult issue?','a thorough understanding of the water shortage','a brief glance at the headline','a promise to repair the bridge','The noun describes insight into how the problem works.')]);
P('understate','From under- + state, “say or present too little”; the verb often contrasts with exaggerate.',[C('understate.s1','低报或轻描淡写','The first budget understated repair costs by omitting the price of replacement cables.','第一份预算漏掉更換電纜的費用，因此低報了維修成本。','understate + cost / figure / severity','Transitive verb: present a fact or amount as lower or less serious than it is.','The reported cost falls below the likely true total.')],[M('The estimate understated the damage at $80,000, though the final repairs cost only $30,000.','The estimate overstated the damage at $80,000, though the final repairs cost only $30,000.','A figure above the eventual cost is overstated, not understated.','word-choice')],[Q('understate.q1','understate.s1','meaning','Why did the budget understate repair costs?','It left out a cost, so the total was too low.','It included every cost twice.','It reported a total above the true amount.','Understate means present an amount or fact too low.'),Q('understate.q2','understate.s1','context','Which speaker understates the damage?','One who calls a major flood “a little leak.”','One who describes a small scratch accurately.','One who doubles the repair estimate.','Calling major damage minor presents it as less serious.'),Q('understate.q3','understate.s1','distinction','What is the opposite action in the $80,000 example?','Overstate the damage.','Understate the damage.','Repair the damage.','A figure above the final cost exaggerates the amount.'),Q('understate.q4','understate.s1','word-choice','Choose the accurate description: the actual queue is 200 people, but the report says 40.','The report understates the queue.','The report overstates the queue.','The report measures the queue exactly.','Forty is below the actual number of 200.')]);
P('understatement','From understate + -ment, the act or result of presenting something as less important or severe than it is.',[C('understatement.s1','轻描淡写','Calling the storm damage “a few wet carpets” was an understatement after the roof collapsed.','屋頂坍塌後，把風暴損害說成「幾張地毯濕了」實在是輕描淡寫。','an understatement of + scale / severity','Noun: a statement that deliberately makes something seem smaller or milder.','The phrase greatly minimizes the actual damage.')],[M('Calling the collapsed roof a catastrophe was an understatement because it made the damage sound much worse than it was.','Calling the collapsed roof “a few wet carpets” was an understatement because it made the damage sound minor.','An understatement makes something seem less serious, not more serious.')],[Q('understatement.q1','understatement.s1','meaning','Why was “a few wet carpets” an understatement?','It made the severe storm damage sound minor.','It described the damage as worse than it was.','It gave an exact inventory of every repair.','An understatement presents something as less serious.'),Q('understatement.q2','understatement.s1','context','Which phrase is an understatement after a building collapses?','“There is a little mess to clean up.”','“The building is completely intact.”','“The engineers measured the site.”','The mild wording downplays a catastrophe.'),Q('understatement.q3','understatement.s1','distinction','What does an understatement do?','It deliberately reduces how large or serious something seems.','It magnifies every detail.','It refuses to make any statement.','The word names deliberate minimization.'),Q('understatement.q4','understatement.s1','word-choice','Choose the understatement for a very long wait.','“We waited a little while” after six hours.','“We waited six hours” in an accurate report.','“We arrived before the line formed.”','The first phrase makes a six-hour delay sound much shorter.')]);
P('understory','From under + story, a forestry term for vegetation growing below the forest’s main canopy.',[C('understory.s1','森林植被','Ferns and young maples formed a dense understory beneath the old oak canopy.','蕨類和楓樹幼苗在老橡樹樹冠下形成茂密的林下植被。','the forest understory beneath + canopy','Noun: shrubs, young trees, and herbs growing below the main tree layer.','The ferns and saplings occupy the lower vegetation layer.')],[M('The understory consisted of the tallest trees forming the forest canopy above every other plant.','The understory consisted of ferns and young trees growing below the forest canopy.','The understory grows beneath the main canopy rather than forming its tallest layer.')],[Q('understory.q1','understory.s1','meaning','Where does the understory grow?','Below the forest’s main tree canopy.','Above the canopy in open air.','Only on the forest floor after all plants die.','The term names vegetation in the lower layer.'),Q('understory.q2','understory.s1','context','Which plants might form a forest understory?','Ferns and young maples under older trees.','Only the highest branches of the oldest trees.','Crops growing in an open field.','Ferns and saplings occupy the layer below the canopy.'),Q('understory.q3','understory.s1','distinction','Which layer is the understory?','Low shrubs beneath the tall trees.','The upper crown of the tallest trees.','The bare sky above the forest.','The prefix under- locates this layer below the canopy.'),Q('understory.q4','understory.s1','word-choice','Choose the natural forestry phrase.','a shaded understory beneath the oaks','an understory above the treetops','an understory of clouds over the woods','The understory is vegetation below the trees’ canopy.')]);
P('undertake','From under- + take, an Old English formation meaning to take on or assume a task or obligation.',[C('undertake.s1','承担任务','The laboratory will undertake a year-long study of river pollution next spring.','實驗室明年春天將承擔一項為期一年的河川污染研究。','undertake a task / study / project','Transitive verb: accept and begin a task or project.','The laboratory takes responsibility for carrying out the study.'),C('undertake.s2','正式承诺','The contractor undertook to replace every unsafe balcony before the building reopened.','承包商承諾在大樓重新開放前更換所有不安全的陽台。','undertake to + verb','Transitive verb: formally promise to do something.','The contractor makes a commitment to complete the work.')],[M('The laboratory undertook a year-long river study but refused to begin or accept responsibility for it.','The laboratory undertook a year-long river study and accepted responsibility for carrying it out.','To undertake a project is to accept and begin it.')],[Q('undertake.q1','undertake.s1','meaning','What will the laboratory undertake?','It will accept and carry out a year-long study.','It will cancel every research project.','It will sell the river.','Sense 1 means accept and begin a task.'),Q('undertake.q2','undertake.s2','context','What did the contractor undertake to do?','Replace every unsafe balcony before reopening.','Close the building permanently without repairs.','Study river pollution for a year.','Undertake to introduces a promise.'),Q('undertake.q3','undertake.s1','distinction','Which sentence uses undertake for accepting a project?','The team undertook an audit of the old records.','The team undertook to return the key by Friday.','The team understood the audit results.','The first takes on a project; the second is a promise.'),Q('undertake.q4','undertake.s2','grammar','Choose the standard promise construction.','They undertook to repair the bridge.','They undertook repairing the bridge to promise.','They undertook the bridge to repair it to.','This verb commonly takes to + infinitive for a commitment.')]);
P('undertaker','From undertake + -er; the funeral sense developed from taking charge of burial arrangements.',[C('undertaker.s1','殡葬业','The undertaker arranged the service and prepared the deceased for burial.','殯葬業者安排了告別式，並為逝者下葬作準備。','consult / hire an undertaker','Noun: a person who prepares the dead and manages funeral arrangements.','The professional is responsible for the funeral preparations.')],[M('The undertaker repaired the roof and built the family’s new house.','The undertaker prepared the deceased and organized the funeral.','An undertaker in this sense manages funerals, not house construction.')],[Q('undertaker.q1','undertaker.s1','meaning','What work does an undertaker do?','Prepares the dead and arranges funerals.','Repairs roofs and builds houses.','Insures ships against storms.','The noun names a funeral professional.'),Q('undertaker.q2','undertaker.s1','context','Who would a family contact to arrange a burial service?','An undertaker.','A ship underwriter.','A forest ranger.','Funeral arrangements are the undertaker’s work.'),Q('undertaker.q3','undertaker.s1','distinction','Which task belongs to an undertaker?','Preparing the deceased for a funeral.','Underwriting a company’s shares.','Surveying a seabed.','The undertaker handles preparation and funeral arrangements.'),Q('undertaker.q4','undertaker.s1','word-choice','Choose the natural sentence.','The undertaker met the family to discuss the service.','The undertaker issued a sea cable survey.','The undertaker measured the forest canopy.','Families meet an undertaker to plan funeral details.')]);
P('undertaking','From undertake + -ing; the noun means either a serious project or a formal commitment.',[C('undertaking.s1','艰巨事业','Restoring the flood-damaged library proved a costly undertaking for the small town.','修復遭洪水損壞的圖書館，對這座小鎮而言是一項耗資巨大的工程。','a major / costly undertaking','Noun: a large, difficult task or project.','The restoration requires substantial effort and resources.'),C('undertaking.s2','承诺','The supplier signed an undertaking to deliver replacement parts within ten days.','供應商簽署了承諾書，保證十天內交付替換零件。','sign / give an undertaking to + verb','Noun: a formal promise to do something.','The supplier formally commits to delivery.')],[M('Repairing the ruined library was a tiny undertaking that required no work, money, or planning.','Repairing the ruined library was a major undertaking requiring work, money, and planning.','A major undertaking is a substantial and difficult project.')],[Q('undertaking.q1','undertaking.s1','meaning','Why was the library restoration an undertaking?','It was a large, costly project.','It was a quick task requiring no effort.','It was a funeral appointment.','The project sense refers to substantial work.'),Q('undertaking.q2','undertaking.s2','context','What did the supplier sign?','A formal promise to deliver parts within ten days.','A plan to build a library.','A report on forest plants.','An undertaking can be a written commitment.'),Q('undertaking.q3','undertaking.s1','distinction','Which is a major undertaking?','Rebuilding a bridge after a flood.','Closing one envelope.','Reading a one-line note.','Rebuilding infrastructure is a large, demanding project.'),Q('undertaking.q4','undertaking.s2','word-choice','Choose the phrase about a formal commitment.','a written undertaking to repay the loan','an undertaking that took five years of construction','a costly undertaking across the whole town','The written undertaking is a promise to repay.')]);
P('undertone','From under + tone, a low or less explicit tone beneath what is overtly expressed.',[C('undertone.s1','言语态度','There was an undertone of impatience in the manager’s polite reply.','經理禮貌的回覆中帶著一絲不耐煩的語氣。','an undertone of + emotion / attitude','Noun: an implied feeling or attitude beneath the explicit words.','The wording is polite, but impatience is indirectly present.')],[M('Her reply had an undertone of warmth because it contained no hint of friendliness or feeling.','Her reply had an undertone of coldness despite its formally polite words.','An undertone is an implied quality beneath the explicit wording.')],[Q('undertone.q1','undertone.s1','meaning','What did the manager’s reply contain beneath its polite wording?','An implied feeling of impatience.','A loud musical bass line.','A direct statement of delight.','The figurative sense is an underlying attitude.'),Q('undertone.q2','undertone.s1','context','Which reply has an undertone of sarcasm?','“Brilliant work,” said after a careless mistake.','“Thank you,” said sincerely after careful help.','“The door is open,” said as a neutral fact.','The praise indirectly conveys criticism.'),Q('undertone.q3','undertone.s1','distinction','What does an undertone describe here?','A feeling implied beneath the surface words.','The loudest sentence in a speech.','A literal musical instrument only.','The figurative noun refers to an underlying attitude.'),Q('undertone.q4','undertone.s1','word-choice','Choose the phrase that naturally takes undertone.','an undertone of resentment in his calm voice','an undertone of a staircase above the room','an undertone of exact arithmetic only','An emotion can be implied beneath a calm voice.')]);
P('undervaluation','From undervalue + -ation, the act or result of assigning too little value.',[C('undervaluation.s1','估值','The audit found an undervaluation of the warehouse because the report ignored its new loading system.','審計發現倉庫估值過低，因為報告忽略了新裝的裝卸系統。','an undervaluation of + asset / property','Noun: an assessment below the true worth of something.','The appraisal omits an improvement and therefore falls short.')],[M('The report’s undervaluation put the warehouse at $9 million even though its true worth was only $6 million.','The report’s overvaluation put the warehouse at $9 million even though its true worth was only $6 million.','A value above the true worth is an overvaluation, not an undervaluation.','word-choice')],[Q('undervaluation.q1','undervaluation.s1','meaning','What did the audit find?','The warehouse had been assessed below its true worth.','The warehouse had been valued above its true worth.','The warehouse had been sold twice.','Undervaluation is an assessment that is too low.'),Q('undervaluation.q2','undervaluation.s1','context','Why was the warehouse’s assessment too low?','It ignored the new loading system.','It counted the loading system twice.','It measured the warehouse’s roof colour.','Omitting a valuable improvement lowers the estimate.'),Q('undervaluation.q3','undervaluation.s1','distinction','Which figure shows undervaluation?','A $6 million estimate for a property truly worth $9 million.','A $10 million estimate for a property worth $9 million.','A $9 million estimate for a property worth $9 million.','The estimate is below the true value.'),Q('undervaluation.q4','undervaluation.s1','word-choice','Choose the noun for an appraisal set too low.','undervaluation','overvaluation','revaluation at the exact price','The prefix under- indicates the assessment is below value.')]);
P('undervalue','From under- + value, “put too low a value on”; it can concern price or importance.',[C('undervalue.s1','估价偏低','The dealer undervalued the violin because its maker’s label was hidden inside the case.','經銷商因看不到琴盒內的製作者標籤，低估了小提琴的價值。','undervalue + object / property','Transitive verb: estimate an object’s worth below its actual value.','The hidden label would have increased the violin’s price.'),C('undervalue.s2','低估重要性','Managers often undervalue the time required to train new staff.','管理者常低估培訓新員工所需的時間。','undervalue + contribution / skill / importance','Transitive verb: fail to recognize how important or good someone or something is.','The training time is more important than managers acknowledge.')],[M('The dealer undervalued the violin by pricing it far above its verified market value.','The dealer overvalued the violin by pricing it far above its verified market value.','A price above the true market value is overvaluation.','word-choice')],[Q('undervalue.q1','undervalue.s1','meaning','Why did the dealer undervalue the violin?','The hidden maker’s label led to an estimate below its worth.','The dealer charged far above its market price.','The violin had no maker or value.','The price sense means estimate worth too low.'),Q('undervalue.q2','undervalue.s2','context','What do managers undervalue in the example?','The time needed to train new staff.','The importance of rushing training.','The violin’s maker label.','The verb can mean fail to recognize importance.'),Q('undervalue.q3','undervalue.s1','distinction','Which action undervalues an antique?','Offering far below its documented market worth.','Offering far above its documented market worth.','Checking its maker’s label before pricing it.','The low offer falls short of real value.'),Q('undervalue.q4','undervalue.s2','word-choice','Choose the sentence about failing to appreciate a contribution.','The committee undervalued her years of volunteer work.','The appraiser undervalued the vase at a low price.','The shop overcharged for the violin.','The first concerns recognizing importance, not a market estimate.')]);
P('underwater','From under + water; the adjective describes a position below water or something fully submerged.',[C('underwater.s1','水下位置','An underwater camera recorded rays moving across the sandy seabed.','水下攝影機拍到魟魚游過沙質海床。','an underwater + device / scene / activity','Adjective: situated or used below the surface of water.','The camera operates below the water surface.'),C('underwater.s2','被水淹没','After the storm, the lower fields were underwater for two days.','暴風雨後，較低的田地被水淹沒了兩天。','be / go underwater','Adjective: covered or submerged by water.','Water completely covers the fields.')],[M('The lower fields were underwater after the storm, but every part stayed completely dry.','The lower fields were underwater after the storm, with water covering them.','If land is underwater, it is covered by water rather than dry.')],[Q('underwater.q1','underwater.s1','meaning','Where did the camera operate?','Below the water’s surface.','Above the clouds.','On a dry hillside.','The first sense locates an object or activity beneath water.'),Q('underwater.q2','underwater.s2','context','What happened to the lower fields after the storm?','Water covered them for two days.','They stayed completely dry.','They sank beneath the earth.','Here underwater means covered or submerged.'),Q('underwater.q3','underwater.s1','distinction','Which is an underwater device?','A camera sealed for filming beneath a lake.','A telescope aimed at the stars.','A radio on a dry desk.','The camera is used below the water surface.'),Q('underwater.q4','underwater.s2','word-choice','Choose the sentence meaning “covered by water.”','The garden went underwater during the flood.','The swimmer used an underwater camera.','The diver surfaced beside the boat.','The floodwater covered the garden.')]);
P('underwear','From under + wear, garments worn next to the body beneath outer clothing.',[C('underwear.s1','衣物','Pack breathable underwear for the long hike because the weather will be warm.','天氣炎熱，長途健行時請帶透氣的貼身內衣。','wear / pack clean underwear','Uncountable noun: garments worn next to the skin under other clothes.','It names the clothing layer beneath outer garments.'),C('underwear.s2','购买与洗涤','The shop stocks children’s underwear in several sizes and washable fabrics.','這家店備有多種尺寸與可水洗布料的兒童內衣。','a pair of underwear; underwear as a category','Uncountable category noun: these garments considered as items for purchase or washing.','The shop sells the clothing category, not one garment type.')],[M('She packed three underwears for the trip.','She packed three pairs of underwear for the trip.','Underwear is generally uncountable; count individual sets as pairs of underwear.','countability')],[Q('underwear.q1','underwear.s1','meaning','Where is underwear worn?','Next to the skin beneath outer clothes.','Over a coat as a rain layer.','Around the feet as shoes.','Underwear is the inner clothing layer.'),Q('underwear.q2','underwear.s2','context','What does the shop stock?','The clothing category in several sizes and fabrics.','Only outer coats.','A single uncountable garment called an underwear.','The category noun refers to garments sold and washed.'),Q('underwear.q3','underwear.s1','grammar','Choose the natural count phrase.','three pairs of underwear','three underwears','three underwear garment','Use pairs of underwear when counting sets.'),Q('underwear.q4','underwear.s2','distinction','Which sign would fit a shop section?','Underwear: cotton, sports, and children’s sizes.','Underwears: one shirt only.','Outerwear: socks and briefs only.','Underwear is a category noun, normally uncountable.')]);
P('underwing','Compound of under + wing, naming the lower surface of a wing or a moth’s hindwing.',[C('underwing.s1','翼面','The biologist photographed the moth’s orange underwing before it folded its wings.','生物學家在飛蛾合起翅膀前拍下了橙色的後翅腹面。','the underwing of a moth / bird','Noun: the underside of a wing, especially a moth’s hindwing.','The orange pattern is on the wing’s lower side.')],[M('The moth displayed its underwing on the upper side of its back, above both wings.','The moth displayed the coloured underside of its hindwing.','An underwing is the lower surface of a wing, not a body surface above it.')],[Q('underwing.q1','underwing.s1','meaning','Where was the moth’s orange pattern?','On the underside of its hindwing.','On the top of its head.','On the upper side of its back.','Underwing names a wing’s lower surface.'),Q('underwing.q2','underwing.s1','context','What did the biologist photograph?','The moth’s lower wing surface before it folded its wings.','The insect’s antennae after it flew away.','A feather lying under a nest.','The underwing was visible before the wings closed.'),Q('underwing.q3','underwing.s1','distinction','Which is an underwing?','The lower face of a moth’s hindwing.','The underside of a bird’s foot.','The top of an aircraft cabin.','The compound refers specifically to a wing surface.'),Q('underwing.q4','underwing.s1','word-choice','Choose the accurate phrase.','a bright pattern on the moth’s underwing','a bright pattern under the moth’s body','a bright pattern above the bird’s wing','The word means the underside of the wing.')]);
P('underworld','From under + world; in mythology it is the world of the dead, and figuratively the criminal world.',[C('underworld.s1','犯罪组织','The journalist traced the stolen paintings through the city’s underworld.','記者循著線索，在這座城市的地下犯罪世界追查失竊畫作。','the criminal / city underworld','Noun: the people and organizations involved in crime.','The investigation follows criminal networks.'),C('underworld.s1','神话','In the myth, the hero descends to the underworld to seek his lost friend.','神話中，英雄下到冥界尋找失去的朋友。','descend to / journey through the underworld','Noun: the imagined place where the dead live.','The hero enters the mythical realm of the dead.')],[M('The journalist followed the city’s underworld, a group of honest volunteers who never committed crimes.','The journalist followed the city’s underworld, a network of criminals dealing in stolen art.','The figurative underworld refers to criminal people and organizations.')],[Q('underworld.q1','underworld.s1','meaning','What did the journalist investigate?','Criminal networks connected to stolen paintings.','A group of museum volunteers.','A scientific study of the ocean floor.','The figurative underworld is the criminal world.'),Q('underworld.q2','underworld.s1','context','Where does the mythic hero go to seek his friend?','To the imagined realm of the dead.','To a city art market.','To the top of a mountain.','The mythic underworld is where the dead live.'),Q('underworld.q3','underworld.s1','distinction','Which phrase uses underworld for organized crime?','the underworld’s stolen-goods network','the underworld of the dead in a legend','the world under the ocean surface','A stolen-goods network belongs to criminal society.'),Q('underworld.q4','underworld.s1','word-choice','Which setting is the mythological underworld?','A hero crosses into the land of the dead.','A reporter interviews a gang leader.','A diver explores a reef.','The first describes the imagined afterlife realm.')]);
P('underwrite','From under + write, originally “sign beneath”; in finance it came to mean guarantee or insure a risk.',[C('underwrite.s1','承保或担保','Several banks agreed to underwrite the bond issue if the company met its safety targets.','若公司達到安全目標，幾家銀行同意為這次債券發行提供承銷擔保。','underwrite a loan / policy / share issue','Verb: insure against loss or guarantee financial support for an issue or project.','The banks promise financial backing under stated conditions.')],[M('The bank underwrote the loan by refusing to guarantee it and transferring all risk away from itself.','The bank underwrote the loan by agreeing to guarantee repayment under the contract.','To underwrite is to provide a guarantee or financial backing, not refuse it.')],[Q('underwrite.q1','underwrite.s1','meaning','What did the banks agree to do?','Guarantee financial backing for the bond issue.','Cancel the company’s safety targets.','Buy the company’s factory outright.','Underwrite means guarantee or support a financial issue.'),Q('underwrite.q2','underwrite.s1','context','What does an insurer do when it underwrites a policy?','It accepts and assesses the risk under the policy.','It refuses all responsibility for the risk.','It repairs the insured property itself.','The insurance sense involves accepting a risk for coverage.'),Q('underwrite.q3','underwrite.s1','distinction','Which action underwrites a project?','A foundation guarantees its funding if conditions are met.','A donor declines to contribute or guarantee money.','A builder paints the project sign.','The foundation provides a financial guarantee.'),Q('underwrite.q4','underwrite.s1','word-choice','Choose the correct use.','The bank will underwrite the new share issue.','The bank will underwrite the company by withholding every guarantee.','The bank will underwrite the rain by opening an umbrella.','A bank can guarantee or finance a share issue.')]);
P('undeserved','From un- “not” + deserved, the past participle of deserve.',[C('undeserved.s1','未应得','The referee apologized for the undeserved penalty after reviewing the replay.','裁判重看回放後，為那次不應判給的罰球道歉。','undeserved praise / blame / punishment','Adjective: not earned or justified by a person’s actions.','The replay showed the player had not committed the offence.')],[M('The player received an undeserved award after years of excellent work that fully merited it.','The player received a deserved award after years of excellent work that fully merited it.','An award earned by excellent work is deserved, not undeserved.','word-choice')],[Q('undeserved.q1','undeserved.s1','meaning','Why was the penalty undeserved?','The replay showed no offence that justified it.','The player clearly committed the offence.','The referee never reviewed the replay.','Undeserved means not earned or justified.'),Q('undeserved.q2','undeserved.s1','context','Which is undeserved blame?','A worker is blamed for a mistake made by someone else.','A worker accepts responsibility for their own error.','A worker receives thanks for careful work.','The blame is not justified by the worker’s actions.'),Q('undeserved.q3','undeserved.s1','distinction','Which phrase matches undeserved praise?','Praise given to someone who did not earn it.','Praise for a carefully completed task.','A neutral description of a result.','Undeserved praise has no sufficient merit behind it.'),Q('undeserved.q4','undeserved.s1','word-choice','Choose the correct description of a baseless punishment.','an undeserved punishment','a well-deserved punishment','a justified reward','The punishment is not merited by the person’s actions.')]);
P('undesirable','From un- “not” + desirable, from desire; it describes something not wanted or likely to cause harm.',[C('undesirable.s1','不受欢迎或有害','The report identified an undesirable side effect that outweighed the medicine’s small benefit.','報告指出一項不受歡迎的副作用，其影響超過藥物帶來的小幅益處。','an undesirable effect / feature / outcome','Adjective: not wanted, often because it may cause harm or dislike.','The side effect is a harmful unwanted result.')],[M('The medicine caused an undesirable effect that every patient welcomed and found beneficial.','The medicine caused a desirable effect that every patient welcomed and found beneficial.','A welcomed beneficial effect is desirable, not undesirable.','word-choice')],[Q('undesirable.q1','undesirable.s1','meaning','Why was the side effect undesirable?','It was unwanted and outweighed the small benefit.','It was welcomed by every patient.','It had no effect on anyone.','Undesirable means not wanted, often because of harm.'),Q('undesirable.q2','undesirable.s1','context','Which outcome is undesirable for a town?','A toxic leak contaminates the drinking water.','A new clinic opens near the school.','A clean park is built for families.','The leak is harmful and unwanted.'),Q('undesirable.q3','undesirable.s1','distinction','Which adjective fits an unwanted consequence?','undesirable','unavoidable','underwater','Undesirable specifically signals that the result is not wanted.'),Q('undesirable.q4','undesirable.s1','word-choice','Choose the sentence using undesirable accurately.','The policy produced an undesirable rise in pollution.','The policy produced an undesirable benefit that residents all wanted.','The policy produced an undesirable result that improved every measure.','The rise in pollution is an unwanted harmful result.')]);
P('undetected','From un- “not” + detected, the past participle of detect.',[C('undetected.s1','未被发现','The leak remained undetected until water appeared beneath the laboratory sink.','直到實驗室水槽下方出現積水，漏水才被發現。','remain / go undetected','Adjective: not noticed or found by observation, tests, or inspection.','The leak existed before anyone noticed it.')],[M('The leak went undetected even though the inspector found it immediately and marked its location.','The leak did not remain undetected because the inspector found it immediately.','Once it is found, the leak is detected rather than undetected.')],[Q('undetected.q1','undetected.s1','meaning','What does undetected mean about the leak?','No one had noticed or found it yet.','It had been repaired and removed.','The inspector had already marked it.','The prefix un- negates detected: not found.'),Q('undetected.q2','undetected.s1','context','When was the leak discovered?','After water appeared beneath the sink.','Before it began leaking.','Immediately during the first inspection.','It remained unnoticed until visible water appeared.'),Q('undetected.q3','undetected.s1','distinction','Which problem remains undetected?','A crack no test or inspector has found.','A crack circled in red on the report.','A repaired crack documented yesterday.','The first has not been discovered.'),Q('undetected.q4','undetected.s1','grammar','Choose the natural phrase.','The fault went undetected for months.','The fault went undetecting for months.','The fault went detect for months.','The adjective follows went in the phrase went undetected.')]);
P('undeveloped','From un- “not” + developed, the past participle of develop.',[C('undeveloped.s1','土地','The council protected an undeveloped stretch of coast from new hotels and roads.','市議會保護一段尚未開發的海岸，避免興建新飯店和道路。','undeveloped land / coast / site','Adjective: land not yet built on or used for industry or trade.','The coast remains without commercial construction.'),C('undeveloped.s2','未成熟','The film showed an undeveloped image because the chemicals had not been applied correctly.','因化學藥劑使用不當，底片上的影像沒有顯影。','an undeveloped skill / image / capacity','Adjective: not yet brought to a complete or mature state.','The image has not reached its finished state.')],[M('The undeveloped coastline was covered with hotels and factories built across every beach.','The developed coastline was covered with hotels and factories built across every beach.','A coast covered in extensive construction is developed, not undeveloped.','word-choice')],[Q('undeveloped.q1','undeveloped.s1','meaning','Why was the coastal stretch undeveloped?','It had no new hotels, roads, or commercial buildings.','It was covered by a city and factories.','It had already become an industrial port.','The land sense means not yet built on or commercially used.'),Q('undeveloped.q2','undeveloped.s2','context','Why did the film show an undeveloped image?','The image had not reached a finished state.','The coast had no hotels.','The camera had no lens.','This sense means not yet brought to completion.'),Q('undeveloped.q3','undeveloped.s1','distinction','Which area is undeveloped?','A protected shore without buildings or industry.','A beach lined with hotels and shops.','A factory district with new roads.','The land has not been commercially built on.'),Q('undeveloped.q4','undeveloped.s2','word-choice','Which phrase uses the unfinished sense?','an undeveloped photographic image','an undeveloped business district full of new towers','an undeveloped road built across the coast','The image has not yet been brought to its finished state.')]);
P('undifferentiated','From un- “not” + differentiated, from differentiate, “mark as different.”',[C('undifferentiated.s1','无明显区分','Under the microscope, the early cells appeared undifferentiated and had no specialized roles.','在顯微鏡下，早期細胞看來尚未分化，沒有專門的功能。','undifferentiated cells / group / mass','Adjective: not separated into distinct types, parts, or roles.','The cells have not acquired specialized identities.')],[M('The cells were undifferentiated because each had a highly specialized and completely different function.','The cells were differentiated because each had a highly specialized and different function.','Specialized distinct functions show differentiation, the opposite of undifferentiated.','word-choice')],[Q('undifferentiated.q1','undifferentiated.s1','meaning','What was true of the early cells?','They had not developed specialized roles.','Each had a unique specialized function.','They were visible only without a microscope.','Undifferentiated cells are not yet distinct by role or type.'),Q('undifferentiated.q2','undifferentiated.s1','context','Which group is undifferentiated?','A set of cells alike in structure and with no separate roles.','A team divided into distinct specialist jobs.','A set of tissues with different functions.','The cells lack distinct types or functions.'),Q('undifferentiated.q3','undifferentiated.s1','distinction','What is the opposite of undifferentiated cells?','Cells specialized into distinct types.','Cells still alike with no roles.','Cells that have not been examined.','Specialization creates differentiation.'),Q('undifferentiated.q4','undifferentiated.s1','word-choice','Choose the accurate report.','The sample contains undifferentiated precursor cells.','The sample contains cells with six specialized roles, so it is undifferentiated.','The sample is undifferentiated because its cells are all named differently.','Precursor cells without specialized roles are undifferentiated.')]);
P('undiluted','From un- “not” + diluted, the past participle of dilute.',[C('undiluted.s1','未稀释液体','The label says to use the cleaner undiluted, without adding water.','標籤說明清潔劑須原液使用，不可加水稀釋。','use / apply undiluted','Adjective: not made weaker by mixing with water or another liquid.','No water has been added to the cleaner.'),C('undiluted.s2','完整未减弱','She spoke with undiluted admiration for the volunteers who stayed through the storm.','她毫不掩飾地讚賞那些在暴風雨中留下來的志工。','undiluted + emotion / enthusiasm / pleasure','Adjective: complete and not weakened by anything else.','Her admiration is wholehearted.')],[M('Apply the cleaner undiluted by mixing one part cleaner with nine parts water first.','Apply the cleaner diluted by mixing one part cleaner with nine parts water first.','Adding water weakens the cleaner, so the mixture is diluted.','word-choice')],[Q('undiluted.q1','undiluted.s1','meaning','How should the cleaner be used?','As it is, without adding water.','Mixed with nine parts water.','Frozen into a solid.','Undiluted means not weakened by mixing with liquid.'),Q('undiluted.q2','undiluted.s2','context','What did she express with undiluted admiration?','Complete, unweakened admiration for the volunteers.','A small amount of water.','Mixed feelings of dislike only.','The figurative sense means full or unweakened.'),Q('undiluted.q3','undiluted.s1','distinction','Which juice is undiluted?','Juice served straight from the bottle with no water added.','Juice mixed with three cups of water.','Juice frozen with ice and melted.','The first has not been mixed with water.'),Q('undiluted.q4','undiluted.s2','word-choice','Which phrase uses the figurative sense?','undiluted joy at the reunion','undiluted vinegar with no water','undiluted paint straight from the tin','Joy is complete and not weakened by other feelings.')]);
P('undiscovered','From un- “not” + discovered, the past participle of discover.',[C('undiscovered.s1','尚未发现','The cave system remained undiscovered until a survey team found a narrow entrance.','直到勘查隊找到狹窄入口前，這片洞穴系統一直未被發現。','remain / lie undiscovered','Adjective: not yet found, known, or recognized.','The caves existed before the team located them.')],[M('The undiscovered cave had been mapped, visited, and described by every local guide for generations.','The well-known cave had been mapped, visited, and described by local guides for generations.','A cave repeatedly mapped and visited is already discovered.')],[Q('undiscovered.q1','undiscovered.s1','meaning','What was the cave like before the survey?','It existed but had not yet been found.','It had been visited by every guide.','It had been sealed after discovery.','Undiscovered means not yet found or known.'),Q('undiscovered.q2','undiscovered.s1','context','Which talent is undiscovered?','A gifted singer no one has heard or recognized.','A performer whose records top the charts.','A singer who has taught music for decades.','The talent has not yet been recognized.'),Q('undiscovered.q3','undiscovered.s1','distinction','Which site remains undiscovered?','A valley absent from maps and unknown to visitors.','A famous valley with marked trails.','A valley surveyed each year.','The first has not been found or made known.'),Q('undiscovered.q4','undiscovered.s1','word-choice','Choose the accurate phrase.','an undiscovered species found during the new survey','an undiscovered species displayed in museums for centuries','an undiscovered landmark visited by tourists daily','The new survey is the first to find the species.')]);
P('undisguised','From un- “not” + disguised, the past participle of disguise.',[C('undisguised.s1','毫不掩饰','He showed undisguised relief when the rescue team returned safely.','救援隊平安返回時，他毫不掩飾地鬆了一口氣。','undisguised + emotion / contempt / delight','Adjective: openly shown, without being hidden or pretended.','His relief is visible and sincere.')],[M('She showed undisguised delight while keeping every sign of happiness carefully hidden.','She showed disguised delight while keeping every sign of happiness carefully hidden.','An emotion carefully hidden is disguised, not undisguised.','word-choice')],[Q('undisguised.q1','undisguised.s1','meaning','How did he show relief?','Openly, without trying to hide it.','By pretending to feel nothing.','By wearing a mask.','Undisguised means openly shown.'),Q('undisguised.q2','undisguised.s1','context','Which reaction is undisguised?','A person smiles broadly with obvious delight.','A person conceals all emotion behind a blank face.','A person wears a costume.','The delight is plain for others to see.'),Q('undisguised.q3','undisguised.s1','distinction','What is undisguised contempt?','Contempt shown openly rather than concealed.','A feeling of respect kept private.','A costume worn to hide identity.','The adjective means not hidden or pretended.'),Q('undisguised.q4','undisguised.s1','word-choice','Choose the natural phrase.','undisguised excitement at the result','undisguised excitement hidden from everyone','undisguised silence that conceals all reaction','Excitement that is visible is openly shown.')]);
P('undisputed','From un- “not” + disputed, past participle of dispute.',[C('undisputed.s1','无争议','For decades, the captain was the undisputed leader of the expedition team.','幾十年來，這位隊長一直是探險隊公認無可爭議的領袖。','undisputed + fact / leader / champion','Adjective: not questioned or challenged by anyone.','No rival contests the captain’s leadership.')],[M('The title was undisputed because three rival teams formally challenged the winner’s claim.','The title was disputed because three rival teams formally challenged the winner’s claim.','A claim that rivals challenge is disputed, not undisputed.','word-choice')],[Q('undisputed.q1','undisputed.s1','meaning','Why was the captain the undisputed leader?','No one challenged the captain’s position.','Several rivals fought to replace the captain.','The team had no expedition.','Undisputed means not questioned or challenged.'),Q('undisputed.q2','undisputed.s1','context','Which claim is undisputed?','A result accepted by all teams without challenge.','A score formally contested by three teams.','A rumour no one has checked.','The result is not challenged.'),Q('undisputed.q3','undisputed.s1','distinction','Which champion is undisputed?','A champion whose title no opponent contests.','A champion facing a formal appeal.','A player who has not yet competed.','No one disputes the title.'),Q('undisputed.q4','undisputed.s1','word-choice','Choose the correct contrast.','an undisputed fact accepted by every side','an undisputed claim under active challenge','an undisputed result reversed by the appeal board','Acceptance without challenge makes a fact undisputed.')]);
P('undistorted','From un- “not” + distorted, the past participle of distort.',[C('undistorted.s1','未变形或失真','The lens produced an undistorted image of the grid, with every line remaining straight.','鏡頭呈現未失真的格線影像，每條線都保持筆直。','an undistorted image / signal / account','Adjective: free from an unwanted change in form, signal, or meaning.','The lines retain their true shape.')],[M('The undistorted recording changed every speaker’s words and made the clear signal impossible to recognize.','The distorted recording changed every speaker’s words and made the clear signal impossible to recognize.','A recording that changes the signal is distorted, not undistorted.','word-choice')],[Q('undistorted.q1','undistorted.s1','meaning','What did the undistorted lens image preserve?','The grid’s straight lines and true shape.','Curved lines introduced by the lens.','Only the colour of the frame.','Undistorted means free from changed shape or signal.'),Q('undistorted.q2','undistorted.s1','context','Which audio is undistorted?','A clean recording that preserves the speaker’s voice.','A recording that changes every word.','A file containing only static.','The signal remains true to the original.'),Q('undistorted.q3','undistorted.s1','distinction','Which report is undistorted?','One that presents the evidence without twisting its meaning.','One that alters the evidence to favour a side.','One that invents facts.','Undistorted can describe meaning free from distortion.'),Q('undistorted.q4','undistorted.s1','word-choice','Choose the accurate phrase.','an undistorted view through the new lens','an undistorted image bent into a curve','an undistorted signal changed into static','The lens view keeps the object’s proper form.')]);
P('undistributed','From un- “not” + distributed, the past participle of distribute.',[C('undistributed.s1','尚未分发','A box of undistributed ballots remained sealed in the election office.','一箱尚未分發的選票仍封存在選務辦公室。','undistributed + supplies / copies / ballots','Adjective: not yet given or delivered to the intended recipients.','The ballots have not been handed out.')],[M('The undistributed ballots had already been delivered to every voter and counted at each home.','The distributed ballots had already been delivered to every voter and counted at each home.','Items already delivered are distributed, not undistributed.','word-choice')],[Q('undistributed.q1','undistributed.s1','meaning','What happened to the ballots?','They had not yet been handed out.','They had been delivered to every voter.','They had been destroyed after counting.','Undistributed means not yet delivered to recipients.'),Q('undistributed.q2','undistributed.s1','context','Which supplies are undistributed?','Boxes of masks still waiting in the depot.','Masks already delivered to every clinic.','Masks used by patients yesterday.','The boxes have not yet been handed out.'),Q('undistributed.q3','undistributed.s1','distinction','When are copies undistributed?','Before they are sent to their intended readers.','After every reader has received one.','After the printer has mailed them.','Distribution is the act of giving them out.'),Q('undistributed.q4','undistributed.s1','word-choice','Choose the sentence using undistributed correctly.','Undistributed food remained in the warehouse.','Undistributed food had reached every family.','Undistributed parcels were delivered yesterday.','Food still in the warehouse has not been distributed.')]);
P('undisturbed','From un- “not” + disturbed, the past participle of disturb.',[C('undisturbed.s1','保持原状','The archaeologists left the sealed chamber undisturbed until the conservation team arrived.','考古學家讓密封墓室保持原狀，直到保存團隊抵達。','leave / remain undisturbed','Adjective: not interrupted, moved, or changed from its original state.','The chamber is deliberately left as found.')],[M('The sealed chamber remained undisturbed after workers moved every object and rebuilt its walls.','The sealed chamber was disturbed after workers moved every object and rebuilt its walls.','Moving objects and rebuilding walls alters the chamber, so it is disturbed.')],[Q('undisturbed.q1','undisturbed.s1','meaning','How was the chamber left?','It was not moved, opened, or changed.','Every object was rearranged.','Its walls were rebuilt.','Undisturbed means left in peace or original state.'),Q('undisturbed.q2','undisturbed.s1','context','Which forest patch is undisturbed?','A patch left untouched by logging or construction.','A patch cleared for a new road.','A patch replanted after excavation.','The first has not been interrupted or changed.'),Q('undisturbed.q3','undisturbed.s1','distinction','What should researchers do to keep a site undisturbed?','Avoid moving or altering its objects.','Remove every object for display.','Build a road through its centre.','Not changing the site keeps it undisturbed.'),Q('undisturbed.q4','undisturbed.s1','word-choice','Choose the natural phrase.','an undisturbed nest watched from a distance','an undisturbed nest after it was moved to a box','an undisturbed site rebuilt by excavators','The original nest is left untouched.')]);
P('undo','From Old English undōn, “reverse or open”; the verb has literal and figurative senses.',[C('undo.s1','解开','Please undo the knot before you pull the rope through the small ring.','請先解開繩結，再把繩子穿過小環。','undo a knot / button / fastening','Transitive verb: open or unfasten something that has been tied or closed.','The knot must be opened before the rope can pass through.'),C('undo.s2','撤销操作','Press this key combination to undo the last change to the spreadsheet.','按這組按鍵可以撤銷對試算表所做的上一項變更。','undo a change / action / command','Transitive verb: reverse the effect of an action.','The previous edit is reversed.'),C('undo.s3','毁掉成果','One careless leak could undo years of work to rebuild public trust.','一次不慎洩密就可能毀掉多年重建公眾信任的努力。','undo years of progress / good work','Transitive verb: spoil or destroy the result of earlier effort.','The leak would damage the accumulated progress.')],[M('Press undo to keep the deleted paragraph exactly as it is and prevent any reversal.','Press undo to restore the paragraph that was deleted.','Undo reverses the last action, so it restores rather than preserves the deletion.')],[Q('undo.q1','undo.s1','meaning','What should you do before pulling the rope through the ring?','Open the knot.','Tie a second knot around it.','Cut the ring in half.','Undo means unfasten a knot.'),Q('undo.q2','undo.s2','context','What happens when you undo the last spreadsheet change?','The previous edit is reversed.','The next five edits are permanently deleted.','The file is printed.','This sense reverses an action.'),Q('undo.q3','undo.s3','distinction','How could a leak undo years of public-trust work?','It could damage the progress already made.','It could unbutton a coat.','It could restore trust automatically.','Figuratively, undo can spoil earlier success.'),Q('undo.q4','undo.s2','word-choice','Which sentence uses undo for a computer action?','I undid the mistaken deletion with the toolbar.','I undid the bow on the gift box.','The scandal undid years of good work.','The toolbar reverses the mistaken action.')]);
P('undocumented','From un- “not” + documented, the past participle of document.',[C('undocumented.s1','缺少法定文件','The clinic offers confidential advice to undocumented workers who fear losing their jobs.','診所為擔心失去工作的無合法文件勞工提供保密諮詢。','undocumented worker / migrant','Adjective: lacking official documents required by law or an authority.','The workers do not have the required official papers.'),C('undocumented.s2','無文字記錄','The archive may contain undocumented repairs that never appeared in the engineer’s log.','檔案館可能留有工程師紀錄簿上未記載的修繕資料。','undocumented change / event / repair','Adjective: not recorded in writing or supported by sources.','The repairs were not entered into the written record.')],[M('The repair was undocumented because the engineer recorded every step in a dated report.','The repair was documented because the engineer recorded every step in a dated report.','A dated written record means the repair is documented.')],[Q('undocumented.q1','undocumented.s1','meaning','Why are the workers described as undocumented?','They lack official papers required by the authorities.','They lack any job skills.','They work in a clinic.','This sense concerns official documentation.'),Q('undocumented.q2','undocumented.s2','context','What makes a repair undocumented?','It is absent from the engineer’s written log.','It is described in a dated report.','It was approved by the archive.','This sense means not recorded in writing.'),Q('undocumented.q3','undocumented.s1','distinction','Which use refers to legal papers?','undocumented migrants seeking official advice','an undocumented repair hidden from the log','an undocumented change to a machine manual','The first concerns required official documents.'),Q('undocumented.q4','undocumented.s2','word-choice','Choose the phrase about missing written records.','an undocumented alteration to the original plan','an undocumented visitor without a passport','an undocumented worker applying for advice','The alteration was never written into the plan record.')]);
P('undoubtedly','From un- “not” + doubt + -ly, an adverb expressing certainty.',[C('undoubtedly.s1','毫无疑问','The bridge is undoubtedly safer after engineers replaced its corroded supports.','工程師更換腐蝕支架後，這座橋無疑更加安全。','undoubtedly + clause / adjective','Adverb: in a way that leaves no reasonable doubt.','The speaker presents the safety improvement as certain.'),C('undoubtedly.s2','句子副词','Undoubtedly, the committee will ask for evidence before approving the proposal.','毫無疑問，委員會在批准提案前會要求提出證據。','undoubtedly, + complete clause','Sentence adverb: used to state strong certainty about a whole claim.','The adverb comments on the speaker’s confidence in the prediction.')],[M('The bridge was undoubtedly safe, although engineers had no evidence and everyone remained unsure.','The bridge was perhaps safe, although engineers had no evidence and everyone remained unsure.','Undoubtedly signals strong certainty, which conflicts with everyone remaining unsure.','context')],[Q('undoubtedly.q1','undoubtedly.s1','meaning','What does the speaker claim about the repaired bridge?','It is certainly safer after the supports were replaced.','It is certainly more dangerous.','Its safety cannot be considered.','Undoubtedly expresses confidence without reasonable doubt.'),Q('undoubtedly.q2','undoubtedly.s2','context','What does “Undoubtedly, the committee will ask for evidence” show?','The speaker is strongly certain about that prediction.','The committee has already rejected the proposal.','The speaker has no view about what will happen.','The opening adverb comments on the whole statement.'),Q('undoubtedly.q3','undoubtedly.s1','distinction','Which sentence uses undoubtedly to strengthen a claim?','The treatment undoubtedly reduced the fever.','The doctor measured the fever at noon.','The patient may or may not have felt better.','The adverb marks the reduction as certain.'),Q('undoubtedly.q4','undoubtedly.s2','grammar','Where can undoubtedly naturally appear as a sentence adverb?','Undoubtedly, the evidence will be reviewed.','Undoubtedly the evidence, will be reviewed.','The evidence undoubtedly, will reviewed.','A comma may follow the opening sentence adverb.')]);
P('undue','From Old English un- “not” + due, “owed or appropriate”; now often “excessive or unjustified.”',[C('undue.s1','过度或不当','The review took care not to place undue pressure on the witness during questioning.','審查時注意不對證人施加過度壓力。','undue pressure / influence / delay','Adjective: excessive or not justified by the circumstances.','The pressure goes beyond what is appropriate.')],[M('The interviewer placed undue pressure on the witness by asking only one calm, necessary question.','The interviewer placed due pressure on the witness by asking only one calm, necessary question.','A single necessary and calm question is not excessive pressure.','word-choice')],[Q('undue.q1','undue.s1','meaning','What does undue pressure mean?','Pressure greater than the situation justifies.','Pressure that is necessary and proportionate.','No pressure at all.','Undue means excessive or unjustified.'),Q('undue.q2','undue.s1','context','Which delay is undue?','A routine permit is held for months without a reason.','A short wait needed to verify a safety check.','A delay caused by a documented storm closure.','An unjustified excessive delay is undue.'),Q('undue.q3','undue.s1','distinction','Which phrase uses undue naturally?','undue influence over the witness','undue gratitude for a thoughtful gift','undue certainty after repeated testing','Influence beyond what is justified can be undue.'),Q('undue.q4','undue.s1','word-choice','Choose the accurate description.','The extra fee placed an undue burden on the family.','The small fair fee placed an undue burden, though it caused no hardship.','The extra fee removed every burden.','An excessive charge can create an unjustified burden.')]);
P('unearned','From un- “not” + earned, the past participle of earn.',[C('unearned.s1','未凭劳动获得','The audit returned the unearned bonus after finding that the sales target had not been met.','審計發現銷售目標未達成後，要求退還未應得的獎金。','unearned income / bonus / praise','Adjective: received without work or merit, or not deserved.','The bonus was not earned under the stated target.')],[M('The employee called the bonus unearned after meeting every target and completing all assigned work.','The employee called the bonus earned after meeting every target and completing all assigned work.','A bonus earned by meeting all targets is not unearned.')],[Q('unearned.q1','unearned.s1','meaning','Why was the bonus unearned?','The employee had not met the sales target required for it.','The employee exceeded every target.','The audit paid the bonus twice.','Unearned means not gained through required work or merit.'),Q('unearned.q2','unearned.s1','context','Which praise is unearned?','A manager praises work that was never completed.','A teacher praises a carefully researched essay.','A team earns an award after a fair competition.','The praise is not supported by actual effort.'),Q('unearned.q3','unearned.s1','distinction','Which income is unearned in the ordinary sense?','A payment received without having done the work for it.','A salary paid for completed work.','A fee earned by providing a service.','The recipient did not earn it through labour or merit.'),Q('unearned.q4','unearned.s1','word-choice','Choose the sentence using unearned correctly.','The audit recovered an unearned commission for a sale never made.','The audit recovered an unearned commission after a completed sale met all terms.','The worker received earned wages for finished work.','No sale was made, so the commission was not earned.')]);
P('unearth','From un- “reverse” + earth, originally to remove earth from around a buried thing; figuratively, discover hidden facts.',[C('unearth.s1','挖掘出土','Workers unearthed a stone drain beneath the courtyard during the renovation.','翻修庭院時，工人挖出了一條石製排水溝。','unearth an object / remains / fossil','Transitive verb: dig something out of the ground where it was buried.','The drain had been hidden beneath the soil.'),C('unearth.s2','揭露真相','The inquiry unearthed emails showing that the safety warning had been ignored.','調查揭露了顯示安全警告遭忽視的電子郵件。','unearth evidence / facts / a secret','Transitive verb: find hidden information after investigation.','The emails were not known before the inquiry.')],[M('The inquiry unearthed the secret by burying every email and refusing to examine any evidence.','The inquiry concealed the secret by burying every email and refusing to examine any evidence.','To unearth information is to reveal it, not hide it.','word-choice')],[Q('unearth.q1','unearth.s1','meaning','What did the workers unearth?','A stone drain buried beneath the courtyard.','A drain suspended above the roof.','A new email account.','The literal verb means dig something out of the ground.'),Q('unearth.q2','unearth.s2','context','What did the inquiry discover?','Emails revealing an ignored safety warning.','A stone drain beneath a courtyard.','A warning that had never existed.','The figurative sense is finding previously hidden information.'),Q('unearth.q3','unearth.s1','distinction','Which action unearths a fossil?','Digging it out of the rock where it was buried.','Hiding it under fresh soil.','Reading an email about it.','The action physically removes something from the earth.'),Q('unearth.q4','unearth.s2','word-choice','Choose the figurative use.','The reporter unearthed records of the secret payments.','The farmer unearthed a buried stone.','The gardener covered the seed with soil.','The reporter uncovered hidden evidence.')]);
P('uneasy','From un- “not” + easy; the adjective describes worry or a lack of calm and security.',[C('uneasy.s1','担忧','Rosa felt uneasy about leaving the lab unlocked overnight.','羅莎對實驗室整夜不上鎖感到不安。','feel / become uneasy about + noun or clause','Adjective: worried and not relaxed about what may happen.','She anticipates a possible security problem.'),C('uneasy.s2','不平稳','The ladder stood on uneven ground and gave the painter an uneasy feeling.','梯子立在不平的地面上，讓油漆工感到不穩。','an uneasy position / peace / feeling','Adjective: not calm or secure, making someone unable to relax.','The physical position feels unstable.')],[M('Rosa felt uneasy about the unlocked lab because she was completely calm and had no concern at all.','Rosa felt at ease about the unlocked lab because she was completely calm and had no concern at all.','A person with no worry is at ease, not uneasy.','word-choice')],[Q('uneasy.q1','uneasy.s1','meaning','Why did Rosa feel uneasy?','She worried about leaving the lab unlocked.','She knew the lab was fully secured.','She was pleased to finish her experiment.','This sense is worry about what may happen.'),Q('uneasy.q2','uneasy.s2','context','Why did the ladder give the painter an uneasy feeling?','Its position on uneven ground felt insecure.','It was firmly secured on level ground.','It had just been painted blue.','This sense describes a lack of physical security or calm.'),Q('uneasy.q3','uneasy.s1','distinction','Which person is uneasy?','A passenger worries about a strange noise in the engine.','A passenger relaxes after learning the engine is fine.','A passenger enjoys a quiet meal.','The first feels concern about a possible problem.'),Q('uneasy.q4','uneasy.s2','word-choice','Choose the phrase about an unstable situation.','an uneasy balance on the narrow ledge','an easy balance on a broad stable floor','a worried thought about tomorrow','The ledge makes the balance physically insecure.')]);
P('uneducated','From un- “not” + educated, the past participle of educate.',[C('uneducated.s1','教育经历','Although she was uneducated in a formal school, she taught herself to read as an adult.','雖然她沒有受過正規學校教育，成年後仍自學識字。','uneducated person / background','Adjective: having received little or no formal schooling.','She lacked school-based education but learned independently.'),C('uneducated.s2','缺乏知识','The article made an uneducated guess about the vaccine without checking the medical evidence.','這篇文章未查證醫學證據，就對疫苗作出缺乏根據的猜測。','an uneducated opinion / guess about + subject','Adjective: lacking knowledge about a particular subject.','The writer has not learned the relevant facts.')],[M('The uneducated article cited three current medical studies and accurately explained their findings.','The well-informed article cited three current medical studies and accurately explained their findings.','Using and accurately explaining current studies shows subject knowledge.')],[Q('uneducated.q1','uneducated.s1','meaning','What was unusual about the woman’s education?','She had no formal schooling but taught herself to read.','She attended university for ten years.','She refused to learn anything as an adult.','The first sense concerns formal schooling.'),Q('uneducated.q2','uneducated.s2','context','Why was the vaccine guess uneducated?','The writer lacked subject knowledge and did not check evidence.','The writer carefully reviewed current medical studies.','The writer had a degree in immunology.','This sense is lack of knowledge about a specific topic.'),Q('uneducated.q3','uneducated.s1','distinction','Which phrase concerns school history?','an uneducated childhood with no access to school','an uneducated opinion about engine repair','an uneducated guess about vaccination','The childhood phrase refers to formal education.'),Q('uneducated.q4','uneducated.s2','word-choice','Which statement uses the topic-knowledge sense?','His uneducated view of geology ignored basic evidence.','He was uneducated because no school accepted him.','She taught herself to read after school closed.','The view lacks knowledge about geology.')]);
P('unemployed','From un- “not” + employed, the past participle of employ.',[C('unemployed.s1','失业者','After the factory closed, Mara was unemployed for six months before finding a new job.','工廠關閉後，瑪拉失業六個月才找到新工作。','be / become unemployed','Adjective: without a paid job although able to work.','She wants work but has no job during that period.'),C('unemployed.s2','失业群体','The grant funds retraining courses for the unemployed in the coastal district.','這筆補助為沿海地區的失業者提供再培訓課程。','the unemployed','Plural noun phrase: people who do not have paid work.','The phrase refers collectively to jobless people.'),C('unemployed.s3','未使用','Several machines stood unemployed after the production line moved to another building.','生產線搬到另一棟大樓後，幾台機器閒置未用。','lie / remain unemployed (of equipment)','Adjective: not being used.','The machines are idle rather than working.')],[M('Mara was unemployed for six months, but during that time she worked full-time at the factory.','Mara was employed for six months, but during that time she worked full-time at the factory.','A person working full-time is employed, not unemployed.','word-choice')],[Q('unemployed.q1','unemployed.s1','meaning','Why was Mara unemployed?','She had no paid job after the factory closed.','She had a new full-time job immediately.','She was unable to work because of retirement.','The first sense means able to work but without a paid job.'),Q('unemployed.q2','unemployed.s2','context','Who receives the retraining grant?','People without paid work, treated as a group.','Only factory machines.','People already working full-time.','The unemployed is a plural group noun.'),Q('unemployed.q3','unemployed.s3','distinction','What happened to the idle machines?','They were not being used.','They had lost their paid jobs.','They were hired by the coastal district.','The third sense can describe unused equipment.'),Q('unemployed.q4','unemployed.s2','grammar','In “courses for the unemployed,” what does the phrase mean?','Courses for people who do not have jobs.','A course for one unemployed machine.','Courses for factory managers only.','The + adjective refers collectively to people.')]);
P('unemployment','From un- “not” + employment; the noun names joblessness and, in some contexts, a benefit payment.',[C('unemployment.s1','失业状态','The town’s unemployment rose after the paper mill closed and several suppliers left.','造紙廠關閉、幾家供應商撤離後，鎮上的失業率上升。','unemployment rises / falls; unemployment rate','Uncountable noun: the state or rate of having no paid work while seeking it.','More people who want work cannot find jobs.'),C('unemployment.s2','失业救济','He used his unemployment to cover rent while he searched for another job.','他找下一份工作期間，靠失業救濟金支付房租。','claim / receive unemployment','Uncountable noun: government money paid to eligible people without jobs.','The money is a benefit during joblessness.')],[M('The town’s unemployment rose because every resident quickly found a secure full-time job.','The town’s employment rose because every resident quickly found a secure full-time job.','If residents find jobs, employment rises and unemployment falls.')],[Q('unemployment.q1','unemployment.s1','meaning','Why did the town’s unemployment rise?','The mill closed and people lost work.','Every resident found a secure job.','The town opened several new factories.','The first sense concerns joblessness or its rate.'),Q('unemployment.q2','unemployment.s2','context','What did he use to pay rent while job hunting?','A government benefit for eligible people without jobs.','A salary from his new full-time job.','A mill’s repair budget.','Unemployment can also name a benefit payment.'),Q('unemployment.q3','unemployment.s1','distinction','Which sentence concerns the jobless rate?','Unemployment fell as local hiring increased.','She applied for unemployment while seeking work.','The clerk mailed a benefit cheque.','The first reports a change in the amount of joblessness.'),Q('unemployment.q4','unemployment.s2','word-choice','Choose the sentence using the benefit sense.','He received unemployment until he found another job.','Unemployment rose when the factory closed.','The town measured unemployment at nine percent.','Receive unemployment means receive the benefit payment.')]);
P('unending','From un- “not” + ending, the present participle of end.',[C('unending.s1','似乎无尽','The crew faced an unending stream of repair requests after the storm damaged the whole district.','暴風雨損壞整個區域後，維修團隊面對似乎沒完沒了的申請。','an unending + series / stream / task','Adjective: continuing for so long that it seems never to stop.','Requests keep arriving without an apparent end.')],[M('The unending queue lasted five seconds and then ended permanently.','The brief queue lasted five seconds and then ended permanently.','Something that ends after five seconds is brief, not unending.')],[Q('unending.q1','unending.s1','meaning','Why did the repair requests seem unending?','They kept arriving with no apparent end.','Only one request arrived and the work stopped.','The crew finished all repairs before the storm.','Unending describes something that seems never to stop.'),Q('unending.q2','unending.s1','context','Which task feels unending?','A backlog grows each day despite hours of work.','A one-minute form is completed immediately.','A project ends exactly on schedule.','The growing backlog seems to have no end.'),Q('unending.q3','unending.s1','distinction','Which is an unending series?','Emails arrive continually throughout the night.','One email arrives once and never again.','A meeting lasts ten minutes as planned.','Continual arrivals make the series seem endless.'),Q('unending.q4','unending.s1','word-choice','Choose the natural phrase.','an unending supply of repair requests','an unending request that stopped at once','an unending task completed in one second','The supply appears to continue without stopping.')]);
P('unequal','From un- “not” + equal, from Latin aequalis, “even or level.”',[C('unequal.s1','不相等或不公平','The two districts received unequal shares of the emergency fund despite serving the same number of families.','兩個地區服務的家庭數相同，分到的緊急基金卻不相等。','unequal shares / treatment / strength','Adjective: different in amount or treatment, or not matched in strength.','One district receives a different and unfairly smaller share.')],[M('The districts received unequal shares: each was given exactly the same amount for the same number of families.','The districts received equal shares: each was given exactly the same amount for the same number of families.','Identical amounts are equal, not unequal.','word-choice')],[Q('unequal.q1','unequal.s1','meaning','Why were the fund shares unequal?','The two districts received different amounts.','Both received exactly the same amount.','Neither district received any families.','Unequal means different in amount or degree.'),Q('unequal.q2','unequal.s1','context','Which contest is unequal?','A professional boxer faces a much smaller untrained opponent.','Two players of similar skill compete under the same rules.','Two teams receive identical equipment.','The opponents are not matched in strength.'),Q('unequal.q3','unequal.s1','distinction','Which treatment is unequal?','One district gets less aid despite serving the same number of families.','Both districts get the same aid for the same need.','A grant is divided evenly by population.','Different treatment under the same circumstances is unequal.'),Q('unequal.q4','unequal.s1','word-choice','Choose the accurate phrase.','unequal access to the same public service','equal access granted to all residents','a perfectly balanced pair of weights','Unequal access means people receive different treatment.')]);
P('uneven','From un- “not” + even, meaning not level or not equal in distribution.',[C('uneven.s1','不平整','The cyclist slowed down on the uneven road, where loose stones covered the surface.','路面凹凸不平又覆著碎石，騎士因此放慢速度。','uneven ground / surface / path','Adjective: not flat or smooth; rising and falling in places.','The road has irregular bumps.'),C('uneven.s2','不均匀','The paint dried in uneven patches because the wall had not been cleaned first.','牆面未先清潔，油漆乾後出現不均勻的斑塊。','uneven distribution / quality / pattern','Adjective: not equal or consistent in different parts.','Some patches have more paint than others.')],[M('The cyclist rode smoothly over an uneven road that was perfectly level and free of bumps.','The cyclist rode smoothly over an even road that was perfectly level and free of bumps.','A level, bump-free road is even rather than uneven.','word-choice')],[Q('uneven.q1','uneven.s1','meaning','Why did the cyclist slow down?','The road surface had bumps and loose stones.','The road was perfectly smooth.','The route was closed for painting.','Uneven in this sense means not flat or smooth.'),Q('uneven.q2','uneven.s2','context','Why did the paint dry in uneven patches?','Different areas had inconsistent amounts of paint.','Every part had exactly the same finish.','The wall was never painted.','This sense means not consistent from part to part.'),Q('uneven.q3','uneven.s1','distinction','Which surface is uneven?','A path with dips and raised stones.','A polished floor that is level throughout.','A flat tabletop checked with a level.','The path rises and falls.'),Q('uneven.q4','uneven.s2','word-choice','Choose the phrase about inconsistent distribution.','uneven rainfall across the region','a level stone floor','an evenly spread blanket','Rainfall differs from one area to another.')]);
P('unevenly','From uneven + -ly, an adverb meaning not equally, smoothly, or consistently.',[C('unevenly.s1','分布不均','The volunteers distributed the food unevenly, leaving one shelter with twice as much as the others.','志工分配食物不均，讓一處收容所拿到其他收容所兩倍的份量。','distribute / spread / wear unevenly','Adverb: in a way that is not equal, smooth, or consistent.','Different shelters receive noticeably different amounts.')],[M('The food was distributed unevenly, with every shelter receiving exactly the same number of boxes.','The food was distributed evenly, with every shelter receiving exactly the same number of boxes.','Equal box counts describe even distribution, not uneven distribution.')],[Q('unevenly.q1','unevenly.s1','meaning','How was the food distributed?','Shelters received different amounts.','Every shelter got exactly the same amount.','No shelter received any food.','Unevenly means not in equal amounts.'),Q('unevenly.q2','unevenly.s1','context','Which surface wears unevenly?','A shoe heel wears down more on one side than the other.','Both heels wear down at exactly the same rate.','The shoes remain unused in a box.','The wear is inconsistent across the heel.'),Q('unevenly.q3','unevenly.s1','distinction','Which sentence uses unevenly as an adverb?','The old engine runs unevenly at low speed.','The old engine is uneven.','The uneven engine is in the shed.','Unevenly modifies how the engine runs.'),Q('unevenly.q4','unevenly.s1','word-choice','Choose the accurate phrase.','The rain fell unevenly across the dry fields.','The rain fell unevenly in the same amount on every field.','The rain was an unevenly surface.','Rainfall varied across the fields.')]);
P('unexpected','From un- “not” + expected, the past participle of expect.',[C('unexpected.s1','出乎意料','An unexpected frost damaged the garden before the seedlings could be covered.','一場意料之外的霜凍在幼苗蓋上防護前損壞了花園。','an unexpected event / result / visitor','Adjective: happening or encountered without being anticipated.','The frost was not predicted or prepared for.'),C('unexpected.s2','偶然选择','They made an unexpected turn at the bridge because the marked road was closed.','標示道路封閉，他們只好在橋邊臨時轉向。','an unexpected choice / direction / turn','Adjective: chosen or happening by chance rather than by plan.','The turn was not part of the planned route.')],[M('The frost was unexpected because the forecast had accurately predicted it a week earlier.','The frost was expected because the forecast had accurately predicted it a week earlier.','An event accurately predicted in advance is expected.')],[Q('unexpected.q1','unexpected.s1','meaning','Why was the frost unexpected?','It was not anticipated before it damaged the garden.','The forecast warned gardeners a week earlier.','The seedlings had already been covered.','The first sense means not anticipated.'),Q('unexpected.q2','unexpected.s2','context','Why did the drivers make an unexpected turn?','A road closure forced a turn not in their plan.','They followed their planned route exactly.','They deliberately returned home.','The turn happened by chance rather than as planned.'),Q('unexpected.q3','unexpected.s1','distinction','Which result is unexpected?','A test reveals a fault no one predicted.','A test confirms the fault announced beforehand.','A planned inspection finds the known issue.','The result was not anticipated.'),Q('unexpected.q4','unexpected.s2','word-choice','Choose the sentence with an unplanned choice.','The hikers took an unexpected path around the flooded bridge.','The hikers followed the route printed on their map.','The hikers arrived at the scheduled trailhead.','The detour was not part of the original plan.')]);
P('unexpectedly','From unexpected + -ly, an adverb meaning in a way not anticipated or planned.',[C('unexpectedly.s1','出乎意料地','The lights unexpectedly came back on while the electrician was checking the fuse box.','電工檢查保險絲盒時，燈光意外地恢復了。','unexpectedly + verb / result','Adverb: in a way that was not expected or planned.','The return of power surprised the people present.')],[M('The lights unexpectedly came back on exactly when the electrician’s written schedule predicted they would.','The lights predictably came back on exactly when the electrician’s written schedule predicted they would.','A precisely scheduled result is predictable, not unexpected.')],[Q('unexpectedly.q1','unexpectedly.s1','meaning','How did the lights come back on?','In a surprising way while the electrician was checking the box.','At the exact time everyone had predicted.','Only after the electrician removed every bulb.','Unexpectedly marks an event that was not anticipated.'),Q('unexpectedly.q2','unexpectedly.s1','context','Which event happened unexpectedly?','A visitor arrived without warning during the meeting.','A guest arrived at the scheduled time after confirming.','The meeting began on its posted schedule.','The arrival was not planned or announced.'),Q('unexpectedly.q3','unexpectedly.s1','grammar','Which word does unexpectedly modify?','In “The engine unexpectedly stopped,” it modifies stopped.','It is a noun naming the engine.','It describes an expected schedule.','The adverb tells how the stopping occurred.'),Q('unexpectedly.q4','unexpectedly.s1','distinction','What does unexpectedly tell the reader?','The event was not anticipated.','The event happened at the planned time.','The speaker knows every future detail.','The adverb marks surprise or lack of planning.')]);
P('unexploited','From un- “not” + exploited, past participle of exploit; it can describe resources or opportunities not yet used.',[C('unexploited.s1','尚未利用','The island’s unexploited geothermal heat could supply power without new fuel imports.','這座島尚未開發的地熱或可在無須進口新燃料的情況下供電。','unexploited resource / potential / opportunity','Adjective: available but not yet used or developed commercially.','The geothermal resource exists but is not yet being used.')],[M('The unexploited reservoir powered every factory in the region for the past decade.','The exploited reservoir powered every factory in the region for the past decade.','A resource already used to power factories is exploited, not unexploited.')],[Q('unexploited.q1','unexploited.s1','meaning','What is true of the island’s geothermal heat?','It is available but has not yet been used.','It has powered the island for decades.','It no longer exists underground.','Unexploited means not yet taken up or commercially developed.'),Q('unexploited.q2','unexploited.s1','context','Which opportunity is unexploited?','A capable team has not yet used a promising research method.','A method used successfully in every project.','A method that has been banned after use.','The opportunity remains available but unused.'),Q('unexploited.q3','unexploited.s1','distinction','Which is an unexploited resource?','A geothermal source with no operating plant.','A coal mine supplying fuel daily.','A river already powering several cities.','The resource has not yet been put to use.'),Q('unexploited.q4','unexploited.s1','word-choice','Choose the accurate phrase.','unexploited potential in the unused research site','unexploited energy already consumed by the factory','unexploited land covered by active mines','The potential remains available but unused.')]);
P('unexplored','From un- “not” + explored, the past participle of explore.',[C('unexplored.s1','未探查','The team marked the northern valley unexplored because no survey had crossed its interior.','由於沒有勘查隊進入北部山谷內部，團隊將其標記為未探索區域。','an unexplored region / route / question','Adjective: not investigated or travelled through.','No survey or expedition has examined the valley.')],[M('The unexplored valley had been mapped in detail and crossed by several survey teams.','The explored valley had been mapped in detail and crossed by several survey teams.','A mapped valley crossed by teams has been explored.')],[Q('unexplored.q1','unexplored.s1','meaning','Why was the northern valley unexplored?','No survey had travelled through its interior.','Several teams had mapped every part.','It was a familiar road through town.','Unexplored means not investigated or travelled through.'),Q('unexplored.q2','unexplored.s1','context','Which question remains unexplored?','A research problem no study has investigated.','A question answered by dozens of studies.','A problem completely solved last year.','No one has yet investigated the problem.'),Q('unexplored.q3','unexplored.s1','distinction','Which territory is unexplored?','A remote island no expedition has visited.','A national park with marked trails and maps.','A site surveyed every summer.','The first has not been travelled through or investigated.'),Q('unexplored.q4','unexplored.s1','word-choice','Choose the accurate sentence.','Researchers entered an unexplored cave for the first time.','Researchers entered an unexplored cave they had mapped yearly for ten years.','The guide led tourists along the well-known cave route.','The first entry means no one had investigated the cave before.')]);
P('unfailingly','From un- “not” + fail + -ing + -ly; it means without ever failing or reliably every time.',[C('unfailingly.s1','始终如一','The night nurse unfailingly checked the oxygen gauge at the start of every shift.','夜班護理師每次交班開始時都必定檢查氧氣錶。','unfailingly + perform / arrive / check','Adverb: on every occasion, in a dependable way.','The check is completed reliably each shift.')],[M('The nurse unfailingly checked the gauge only once in ten shifts and often forgot it.','The nurse occasionally checked the gauge but often forgot it.','A person who often forgets a task does not perform it unfailingly.')],[Q('unfailingly.q1','unfailingly.s1','meaning','How did the nurse check the gauge?','Reliably at the start of every shift.','Only once in ten shifts.','Only when the gauge alarmed.','Unfailingly means on every occasion without fail.'),Q('unfailingly.q2','unfailingly.s1','context','Which person acts unfailingly?','A guard checks each entrance every hour, every night.','A guard checks only when reminded.','A guard skips most scheduled checks.','The first carries out the task reliably each time.'),Q('unfailingly.q3','unfailingly.s1','grammar','What does unfailingly modify in “She unfailingly arrives early”?','The regularity of her arriving.','The noun she.','The early morning itself.','The adverb modifies arrives and means every time.'),Q('unfailingly.q4','unfailingly.s1','distinction','Which phrase matches unfailingly?','without missing a single scheduled check','once after several missed checks','only if the weather is clear','The task is done every time, reliably.')]);
P('unfair','From un- “not” + fair, ultimately from Old English fæger, “beautiful, pleasant,” with a later justice sense.',[C('unfair.s1','不公正','The hiring rule was unfair because it rejected qualified applicants from only one neighbourhood.','這項招聘規則只拒絕某一街區的合格申請者，因此並不公平。','unfair rule / treatment / decision','Adjective: not just because people are treated differently without good reason.','Qualified candidates receive unequal treatment.')],[M('The hiring rule was unfair because every qualified applicant was judged by the same clear criteria.','The hiring rule was fair because every qualified applicant was judged by the same clear criteria.','Equal, consistent criteria describe fair treatment, not unfair treatment.','word-choice')],[Q('unfair.q1','unfair.s1','meaning','Why was the hiring rule unfair?','It rejected qualified people from one neighbourhood only.','It used the same criteria for every applicant.','It accepted every qualified candidate.','The rule treats comparable people differently without good reason.'),Q('unfair.q2','unfair.s1','context','Which decision is unfair?','One student is punished for a rule that others may break.','Every student receives the same chance to appeal.','The teacher applies one rule consistently.','The punishment is unequal without justification.'),Q('unfair.q3','unfair.s1','distinction','Which situation is fair rather than unfair?','All applicants are assessed by identical job-related criteria.','Only applicants from one street are rejected.','A rule is changed for one friend.','Consistent relevant criteria are just.'),Q('unfair.q4','unfair.s1','word-choice','Choose the accurate sentence.','The one-sided rule was unfair to qualified families.','The rule was unfair because it treated every family equally.','The decision was unfair because no one was disadvantaged.','The rule disadvantages a group without justification.')]);
P('unfairly','From unfair + -ly, an adverb meaning without fairness or justice.',[C('unfairly.s1','不公平地','The referee unfairly penalized the visiting team for an error the home team also made.','裁判不公平地處罰客隊，儘管主隊也犯了同樣錯誤。','treat / judge / penalize unfairly','Adverb: in a way that is not fair or just.','The referee applies the rule differently to the two teams.')],[M('The referee unfairly gave both teams the same penalty under the same rule.','The referee fairly gave both teams the same penalty under the same rule.','Applying the same penalty to both teams is fair rather than unfair.')],[Q('unfairly.q1','unfairly.s1','meaning','How did the referee treat the teams unfairly?','The visiting team was penalized while the home team was not for the same error.','Both teams received the same penalty.','Neither team committed an error.','Unfairly describes unjust unequal treatment.'),Q('unfairly.q2','unfairly.s1','context','Which worker was judged unfairly?','One was blamed for a delay caused by the manager.','One was evaluated using the same clear standards as peers.','One received credit for completed work.','Blaming someone for another person’s delay is unjust.'),Q('unfairly.q3','unfairly.s1','grammar','What does unfairly modify in “The firm treated the applicants unfairly”?','The manner of treating the applicants.','The noun applicants.','The firm’s building.','The adverb modifies the verb treated.'),Q('unfairly.q4','unfairly.s1','distinction','Which phrase means without justice?','unfairly denied a hearing','fairly given an equal chance','carefully measured the distance','The denial of a hearing is unjust treatment.')]);
P('unfamiliar','From un- “not” + familiar, from family; it describes something not known through experience or study.',[C('unfamiliar.s1','陌生事物','The hikers stopped at an unfamiliar junction and checked the map before choosing a trail.','健行者在陌生的岔路口停下，查看地圖後才選路。','an unfamiliar place / face / sound','Adjective: not known because it has not been seen or experienced before.','They have never encountered this junction.'),C('unfamiliar.s2','不熟悉领域','Although she is an experienced doctor, tax law is unfamiliar to her.','雖然她是資深醫師，卻不熟悉稅法。','unfamiliar with + subject / procedure','Adjective: not known because one lacks experience or knowledge of a subject.','She has little knowledge of tax law.')],[M('Tax law was unfamiliar to her, but she had studied it for years and could explain every rule.','Tax law was familiar to her, because she had studied it for years and could explain every rule.','Years of study and command of the rules make the subject familiar.')],[Q('unfamiliar.q1','unfamiliar.s1','meaning','Why did the hikers stop at the junction?','They had not seen that place before and checked the map.','They walked the route every week.','The junction was closed by a storm.','Unfamiliar means not previously encountered.'),Q('unfamiliar.q2','unfamiliar.s2','context','What was unfamiliar to the doctor?','Tax law, a subject outside her experience.','Medicine, the subject of her career.','The route she hiked every day.','This sense means lacking knowledge of a topic.'),Q('unfamiliar.q3','unfamiliar.s1','distinction','Which face is unfamiliar?','A face the visitor has never seen before.','A close friend’s face.','A portrait studied for years.','The visitor has no prior experience with it.'),Q('unfamiliar.q4','unfamiliar.s2','word-choice','Choose the natural construction.','This procedure is unfamiliar to new staff.','New staff are unfamiliar from this procedure.','This procedure unfamiliar to new staff is.','Unfamiliar commonly takes to or with.')]);
P('unfasten','From un- “reverse” + fasten, “make secure”; it means open a fastening or loosen something attached.',[C('unfasten.s1','打开扣件','Please unfasten your seat belt only after the bus has stopped.','請等公車停妥後再解開安全帶。','unfasten a belt / button / zip','Transitive verb: open a fastening such as a button, zip, or belt.','The belt’s clasp is released.'),C('unfasten.s2','松开取下','The mechanic unfastened the panel so she could remove it from the engine.','技師鬆開面板的固定件，以便從引擎上拆下它。','unfasten a panel / cover from + object','Transitive verb: make something loose so it can be detached.','The fastening is released before the panel is taken away.')],[M('Passengers should unfasten their seat belts while the bus is still moving at highway speed.','Passengers should unfasten their seat belts only after the bus has stopped.','A safety belt should remain fastened while the vehicle is moving.')],[Q('unfasten.q1','unfasten.s1','meaning','When should passengers unfasten their belts?','After the bus has stopped.','While it is moving at highway speed.','Before they sit down.','Unfasten means release the belt clasp.'),Q('unfasten.q2','unfasten.s2','context','Why did the mechanic unfasten the panel?','To loosen it so she could remove it from the engine.','To glue it permanently in place.','To drain fuel from the tank.','This sense makes the panel loose enough to detach.'),Q('unfasten.q3','unfasten.s1','distinction','Which action unfastens a coat?','Undoing its front buttons.','Sewing the buttons more tightly.','Putting the coat on a hanger.','Opening the buttons releases the fastening.'),Q('unfasten.q4','unfasten.s2','word-choice','Choose the accurate instruction.','Unfasten the cover before lifting it off the machine.','Unfasten the cover by welding it permanently to the machine.','Unfasten the cover without loosening any attachment.','The cover must be released from its fasteners first.')]);
P('unfastened','From un- “not” + fastened, the past participle of fasten.',[C('unfastened.s1','未扣好','The child’s unfastened helmet strap swung beneath her chin as she rode.','孩子騎車時，沒扣好的安全帽帶在下巴下晃動。','an unfastened belt / button / strap','Adjective: not secured by a fastening, so it may open or come loose.','The strap is not buckled in place.')],[M('The unfastened helmet strap held the helmet securely in place because it was tightly buckled.','The fastened helmet strap held the helmet securely in place because it was tightly buckled.','A tightly buckled strap is fastened, not unfastened.','word-choice')],[Q('unfastened.q1','unfastened.s1','meaning','What was wrong with the child’s helmet strap?','It was not secured and swung beneath her chin.','It was tightly buckled.','It was missing from the helmet.','Unfastened means not secured by its clasp.'),Q('unfastened.q2','unfastened.s1','context','Which object is unfastened?','A coat with its buttons undone.','A belt clicked securely into its buckle.','A sealed jar with an intact lid.','The coat can open because its buttons are undone.'),Q('unfastened.q3','unfastened.s1','distinction','Which description fits an unfastened gate?','Its latch has not been secured.','Its latch is locked firmly.','Its hinges have been removed.','The gate is not secured by its fastening.'),Q('unfastened.q4','unfastened.s1','word-choice','Choose the natural phrase.','an unfastened seat-belt buckle','an unfastened buckle clicked securely shut','an unfastened lock that cannot be opened','The buckle is not fastened in the first phrase.')]);
P('unfavorable','From un- “not” + favorable, from favor; it means adverse or expressing disapproval.',[C('unfavorable.s1','不利条件','The climbers postponed the ascent because the forecast predicted unfavorable winds.','氣象預報風勢不利，登山者因此延期攀登。','unfavorable conditions / odds / weather','Adjective: adverse to success or not helping a purpose.','The wind would make the climb less safe.'),C('unfavorable.s1','负面评价','The proposal received an unfavorable review from the independent panel.','這項提案受到獨立評審小組的負面評價。','an unfavorable review / opinion','Adjective: showing that somebody does not support or think well of something.','The panel expresses disapproval.')],[M('The forecast was unfavorable for climbing because it promised calm skies and safe, steady winds.','The forecast was favorable for climbing because it promised calm skies and safe, steady winds.','Calm, safe winds help the climb; they are favorable conditions.','word-choice')],[Q('unfavorable.q1','unfavorable.s1','meaning','Why did the climbers postpone the ascent?','The forecast predicted winds that made climbing unsafe.','The forecast promised calm, safe winds.','The mountain had disappeared.','Unfavorable conditions work against success or safety.'),Q('unfavorable.q2','unfavorable.s1','context','What did the panel’s unfavorable review express?','A negative opinion of the proposal.','Strong support and approval.','A neutral weather report.','The adjective can mean disapproving.'),Q('unfavorable.q3','unfavorable.s1','distinction','Which condition is unfavorable to planting?','A long drought with no rain.','Steady rain and mild temperatures.','Rich soil with enough water.','The drought works against healthy growth.'),Q('unfavorable.q4','unfavorable.s1','word-choice','Choose the phrase meaning “negative in its judgment.”','an unfavorable assessment of the plan','an unfavorable wind that delays a boat','a favorable review praising the plan','The assessment expresses disapproval.')]);
P('unfavorably','From unfavorable + -ly, an adverb meaning in an adverse or disapproving manner.',[C('unfavorably.s1','不利地','The revised route compared unfavorably with the old one because it added two hours of travel.','新路線比舊路線差，因為行程多了兩小時。','compare / react / judge unfavorably','Adverb: in a way that is adverse or shows disapproval.','The new route performs worse in comparison.')],[M('The new route compared unfavorably with the old one because it was faster, safer, and less costly.','The new route compared favorably with the old one because it was faster, safer, and less costly.','Better speed, safety, and cost make the comparison favorable, not unfavorable.','word-choice')],[Q('unfavorably.q1','unfavorably.s1','meaning','Why did the revised route compare unfavorably?','It took two hours longer than the old route.','It was faster and safer.','It cost less and saved time.','The adverb signals a worse comparison.'),Q('unfavorably.q2','unfavorably.s1','context','Which review describes a product unfavorably?','The reviewer points out serious faults and recommends against buying it.','The reviewer praises its quality and recommends it.','The reviewer lists its colour without judgment.','The review expresses negative judgment.'),Q('unfavorably.q3','unfavorably.s1','grammar','What does unfavorably modify in “The report compared unfavorably”?','The manner or result of the comparison.','The noun report as a person.','The time the report was printed.','The -ly adverb modifies compared.'),Q('unfavorably.q4','unfavorably.s1','distinction','Which result is described unfavorably?','The new model performed worse than its predecessor.','The new model outperformed its predecessor.','Both models performed equally well.','A worse comparison is unfavorable.')]);
P('unfavourable','British spelling variant of unfavorable, from un- “not” + favourable; the senses are adverse and disapproving.',[C('unfavourable.s1','不利条件','The match was postponed because unfavourable weather made the playing field unsafe.','天氣不佳使球場變得不安全，因此比賽延期。','unfavourable conditions / odds','Adjective: not giving an advantage or likely to help.','The weather works against safe play.'),C('unfavourable.s2','負面看法','The inspector gave an unfavourable report on the building’s fire exits.','檢查員對大樓的消防出口提出負面報告。','an unfavourable report / opinion','Adjective: showing lack of support or a poor opinion.','The report criticizes the fire exits.')],[M('The inspector gave an unfavourable report while praising every exit as safe and fully compliant.','The inspector gave a favourable report while praising every exit as safe and fully compliant.','Praise for safe, compliant exits is favourable rather than unfavourable.','word-choice')],[Q('unfavourable.q1','unfavourable.s1','meaning','Why was the match postponed?','Weather made the playing field unsafe.','The weather gave both teams an advantage.','The field was dry and safe.','This sense describes adverse conditions.'),Q('unfavourable.q2','unfavourable.s2','context','What did the inspector’s unfavourable report express?','A negative opinion about the fire exits.','Full approval of every exit.','No opinion about building safety.','The second sense shows disapproval.'),Q('unfavourable.q3','unfavourable.s1','distinction','Which forecast is unfavourable for sailing?','A severe storm with dangerous waves.','A steady breeze and clear skies.','Calm water and good visibility.','The storm works against safe sailing.'),Q('unfavourable.q4','unfavourable.s2','word-choice','Choose the sentence with the British spelling.','The committee issued an unfavourable judgment.','The committee issued an un-favourable judgment.','The committee issued an unfavorablly judgment.','Unfavourable is the standard British variant spelling.')]);
P('unfeigned','From un- “not” + feigned, past participle of feign, “pretend.”',[C('unfeigned.s1','真诚情感','Her unfeigned gratitude was clear when she thanked the volunteers one by one.','她逐一向志工道謝時，真摯的感激之情顯而易見。','unfeigned + emotion / interest / apology','Adjective: real and sincere, not pretended.','Her gratitude is genuine rather than performed.')],[M('His unfeigned apology was a performance; he did not mean a single word of it.','His feigned apology was a performance; he did not mean a single word of it.','An apology that is only a performance is feigned, not unfeigned.','word-choice')],[Q('unfeigned.q1','unfeigned.s1','meaning','What was true of her gratitude?','It was genuine and not pretended.','She performed it without meaning it.','She refused to thank anyone.','Unfeigned means sincere.'),Q('unfeigned.q2','unfeigned.s1','context','Which smile is unfeigned?','A spontaneous smile from someone delighted by the news.','A forced smile used to hide annoyance.','A painted smile on a mask.','The first is genuine rather than pretended.'),Q('unfeigned.q3','unfeigned.s1','distinction','Which phrase fits unfeigned?','unfeigned concern for the injured hikers','feigned concern to impress the cameras','a rehearsed apology the speaker does not mean','Unfeigned concern is real and sincere.'),Q('unfeigned.q4','unfeigned.s1','word-choice','Choose the sentence using unfeigned accurately.','The child showed unfeigned delight at seeing her father.','The actor’s unfeigned surprise was carefully faked for the scene.','His unfeigned praise concealed his actual contempt.','Her delight is genuine rather than disguised.')]);
P('unfertilized','From un- “not” + fertilized, past participle of fertilize; biology uses it for an egg not joined by male gametes.',[C('unfertilized.s1','生物學','The researcher examined an unfertilized egg before any sperm had reached it.','精子尚未接觸卵子前，研究人員先檢查了未受精的卵。','an unfertilized egg / ovum','Adjective: not joined with male gametes; also soil not treated with fertilizer.','No fertilization has occurred.')],[M('The unfertilized egg had already joined with a sperm cell and begun developing as an embryo.','The fertilized egg had already joined with a sperm cell and begun developing as an embryo.','An egg joined with a sperm cell is fertilized.')],[Q('unfertilized.q1','unfertilized.s1','meaning','What had not happened to the egg?','It had not joined with a sperm cell.','It had already developed into an embryo.','It had been planted in soil.','Unfertilized means fertilization has not occurred.'),Q('unfertilized.q2','unfertilized.s1','context','Which sample is an unfertilized egg?','An egg examined before any sperm reached it.','An egg after sperm joined and development began.','A seedling growing in a field.','No male gamete has joined the egg.'),Q('unfertilized.q3','unfertilized.s1','distinction','Which soil is unfertilized?','Soil to which no fertilizer has been added.','Soil enriched with compost and nutrients.','Soil in which a fertilized egg is developing.','The adjective can also mean not treated with fertilizer.'),Q('unfertilized.q4','unfertilized.s1','word-choice','Choose the accurate biological phrase.','an unfertilized ovum before sperm contact','an unfertilized embryo after fertilization','an unfertilized egg joined to sperm','The ovum remains unfertilized before sperm contact.')]);
P('unfilled','From un- “not” + filled, past participle of fill; it describes a vacant position or an incomplete container or form.',[C('unfilled.s1','职位空缺','The department advertised its unfilled research post again after the first search produced no suitable candidate.','第一次招聘沒有找到合適人選後，部門再次刊登尚未填補的研究職缺。','an unfilled post / vacancy / position','Adjective: not yet occupied, so somebody can still be chosen.','No candidate has taken the post.'),C('unfilled.s2','未填满或未完成','Return the unfilled form to the desk so the clerk can show you which fields are missing.','請把未填妥的表格交回櫃檯，職員會指出缺少哪些欄位。','an unfilled container / form / space','Adjective: not completed or not filled to the top.','Some fields remain blank.')],[M('The post was unfilled even though a qualified candidate had already been appointed to it.','The post was filled because a qualified candidate had already been appointed to it.','An appointed candidate means the post is filled.')],[Q('unfilled.q1','unfilled.s1','meaning','Why was the research post unfilled?','No suitable candidate had taken it.','A qualified candidate had started work.','The department had closed the post.','The vacancy remains open for someone to be chosen.'),Q('unfilled.q2','unfilled.s2','context','What was wrong with the returned form?','Some fields had not been completed.','Every box contained the requested information.','The clerk had already approved it.','This sense means incomplete.'),Q('unfilled.q3','unfilled.s1','distinction','Which position is unfilled?','A vacancy still awaiting an appointment.','A job held by a newly hired worker.','A role eliminated from the organization.','The position has no person in it yet.'),Q('unfilled.q4','unfilled.s2','word-choice','Choose the phrase describing a container below its capacity.','an unfilled glass with room for more water','an unfilled glass filled to the rim','an unfilled box packed tightly with objects','The glass is not full.')]);
P('unfit','From un- “not” + fit, “suitable or in good condition.”',[C('unfit.s1','不适合或健康不佳','The safety inspector declared the old ladder unfit for use after finding a cracked rung.','安全檢查員發現梯級裂開後，判定舊梯不適合使用。','unfit for + purpose / work / exercise','Adjective: not suitable for a purpose or not in good physical condition.','The damaged ladder is unsafe for its intended use.')],[M('The inspector declared the ladder unfit for use after confirming that every rung was sound and safe.','The inspector declared the ladder fit for use after confirming that every rung was sound and safe.','A sound, safe ladder is fit for use.')],[Q('unfit.q1','unfit.s1','meaning','Why was the ladder unfit for use?','A cracked rung made it unsafe.','Every rung was sound and safe.','It was too short to reach the roof but otherwise safe.','Unfit means unsuitable for its intended purpose.'),Q('unfit.q2','unfit.s1','context','Which person is physically unfit for the race?','A runner who cannot safely complete the required distance.','A trained runner who finishes comfortably.','A spectator watching from the stands.','This sense refers to poor physical condition.'),Q('unfit.q3','unfit.s1','distinction','Which item is unfit for drinking water?','A cracked bottle that leaks and may contaminate the water.','A clean sealed bottle approved for food use.','A tested glass jar in good condition.','The damaged bottle is unsuitable for the purpose.'),Q('unfit.q4','unfit.s1','word-choice','Choose the natural phrase.','unfit for human consumption','unfit for use because it passed every safety test','unfit for a purpose it performs safely and well','The phrase marks something as unsuitable or unsafe.')]);
P('unfixed','From un- “not” + fixed, past participle of fix; it can mean physically loose or not yet settled.',[C('unfixed.s1','未固定','The technician placed a warning tag beside the unfixed cable hanging from the ceiling.','技師在天花板上垂下的未固定電纜旁掛上警示牌。','an unfixed cable / part / object','Adjective: not fastened or secured in place, so it can move.','The cable is loose rather than attached.'),C('unfixed.s2','未决定','The launch date remained unfixed while the team waited for the final safety results.','團隊等待最後的安全結果時，發布日期仍未確定。','remain / leave a date unfixed','Adjective: not yet decided or settled.','No final date has been chosen.')],[M('The cable was unfixed even though it had been bolted securely to the ceiling.','The cable was fixed because it had been bolted securely to the ceiling.','A securely bolted cable is fixed in place.')],[Q('unfixed.q1','unfixed.s1','meaning','Why did the technician tag the cable?','It hung loose and was not secured in place.','It was bolted firmly to the ceiling.','It had been removed and stored safely.','The physical sense means not fastened.'),Q('unfixed.q2','unfixed.s2','context','Why was the launch date unfixed?','The team was still waiting for safety results.','The date had been announced and confirmed.','The launch had already happened.','This sense means not yet decided.'),Q('unfixed.q3','unfixed.s1','distinction','Which part is unfixed?','A loose shelf bracket that can move.','A bracket secured by four bolts.','A bracket welded to the frame.','The loose part is not secured in place.'),Q('unfixed.q4','unfixed.s2','word-choice','Choose the sentence about an unsettled plan.','The final meeting time is still unfixed.','The chair was unfixed and slid across the floor.','The screw remained unfixed in its loose hole.','The meeting time has not yet been decided.')]);
P('unfocused','From un- “not” + focused, past participle of focus; it describes blurred vision or attention without a clear aim.',[C('unfocused.s1','模糊影像','The camera produced an unfocused photograph because the lens moved during exposure.','曝光時鏡頭移動，導致相機拍出的照片失焦模糊。','an unfocused image / photograph','Adjective: blurred because it is not in clear focus.','Details are not sharply defined.'),C('unfocused.s1','注意力不集中','After working through the night, the student felt unfocused during the morning lecture.','熬夜工作後，學生在早上的課堂上覺得注意力難以集中。','feel / seem unfocused','Adjective: lacking clear concentration or direction.','Fatigue makes it hard to direct attention.')],[M('The photograph was unfocused, with every edge perfectly sharp and clear.','The photograph was focused, with every edge perfectly sharp and clear.','Sharp, clear edges show that an image is focused.')],[Q('unfocused.q1','unfocused.s1','meaning','Why was the photograph unfocused?','The lens moved and left the image blurred.','The edges were sharply defined.','The camera was never used.','Unfocused can mean not sharply in focus.'),Q('unfocused.q2','unfocused.s1','context','Why did the student feel unfocused?','Working all night made concentration difficult.','The student slept well and felt alert.','The lecture had already ended.','The mental sense means lacking concentration.'),Q('unfocused.q3','unfocused.s1','distinction','Which use is about attention?','She felt unfocused after hours without a break.','The unfocused image blurred the sign.','The lens produced an unfocused photo.','The first describes concentration rather than image sharpness.'),Q('unfocused.q4','unfocused.s1','word-choice','Choose the phrase about a camera result.','an unfocused portrait with blurred eyes','an unfocused student unable to concentrate','an unfocused plan without a clear goal','The portrait is optically blurred.')]);
P('unfold','From un- “reverse” + fold; it also developed a figurative sense of events happening or becoming clear.',[C('unfold.s1','展开','The guide unfolded the paper map on the bonnet and traced the mountain route.','導遊在引擎蓋上展開紙地圖，描出通往山區的路線。','unfold a map / cloth / letter','Transitive verb: open something that has been folded.','The folded map is opened flat.'),C('unfold.s2','事情发展','Investigators watched the rescue operation unfold through a live radio report.','調查人員透過即時廣播報導，關注救援行動的進展。','events / a story / a plan unfold','Intransitive verb: happen or become clear gradually.','The operation develops over time.')],[M('She unfolded the map by folding it into a smaller square and putting it away.','She folded the map into a smaller square and put it away.','Folding makes it smaller; unfolding opens it out.')],[Q('unfold.q1','unfold.s1','meaning','What did the guide do to the map?','Opened it flat from its folded shape.','Folded it into a smaller square.','Drew a new road on the bonnet.','The literal verb means open something folded.'),Q('unfold.q2','unfold.s2','context','How did the rescue operation unfold?','It developed over time and was followed live.','It was folded into a paper map.','It ended before investigators heard about it.','The figurative sense is events happening gradually.'),Q('unfold.q3','unfold.s1','distinction','Which action unfolds a letter?','Opening its folded pages.','Sealing it in an envelope.','Tearing it into strips.','The paper is opened from a folded shape.'),Q('unfold.q4','unfold.s2','word-choice','Choose the figurative use.','The negotiations unfolded over several difficult weeks.','She unfolded the blanket before making the bed.','He unfolded the paper map on the table.','The negotiations developed over time.')]);
P('unforeseen','From un- “not” + foreseen, past participle of foresee.',[C('unforeseen.s1','未预见情况','An unforeseen delay at the border forced the delivery truck to miss its appointment.','邊境出現未預料的延誤，貨車因此錯過預約時間。','unforeseen event / delay / expense','Adjective: not seen, anticipated, or planned for in advance.','The delay was not anticipated when the delivery was scheduled.')],[M('The delay was unforeseen even though the carrier had scheduled it and warned the customer a month earlier.','The delay was foreseen even though the carrier had scheduled it and warned the customer a month earlier.','A delay announced and planned in advance was foreseen.')],[Q('unforeseen.q1','unforeseen.s1','meaning','Why was the border delay unforeseen?','It had not been anticipated when delivery was scheduled.','The carrier warned about it a month earlier.','The driver deliberately waited a day.','Unforeseen means not predicted in advance.'),Q('unforeseen.q2','unforeseen.s1','context','Which cost is unforeseen?','A sudden emergency repair not included in the budget.','A monthly rent payment listed in the budget.','A planned purchase approved last year.','The repair was not anticipated or planned.'),Q('unforeseen.q3','unforeseen.s1','distinction','Which event is unforeseen?','A pipe bursts during a routine inspection without warning.','A storm is forecast a week ahead.','A scheduled meeting starts on time.','The burst was not seen or planned for.'),Q('unforeseen.q4','unforeseen.s1','word-choice','Choose the natural phrase.','unforeseen circumstances forced the flight to divert','foreseen circumstances arrived without anyone predicting them','unforeseen plans were confirmed months ago','The circumstances were not predicted beforehand.')]);
P('unfortunate','From un- “not” + fortunate, from fortune; it describes bad luck or something tactless in context.',[C('unfortunate.s1','不幸遭遇','It was unfortunate that the storm destroyed the tents just before the festival opened.','節慶即將開幕時暴風雨摧毀帳篷，真是不幸。','it is unfortunate that + clause','Adjective: unlucky or caused by bad luck.','The damage is an unlucky event.'),C('unfortunate.s2','不合时宜','His joke about the budget was unfortunate during a meeting about staff layoffs.','在討論裁員的會議上，他拿預算開玩笑並不妥當。','an unfortunate remark / choice / time','Adjective: unsuitable or tactless in a particular situation.','The joke is inappropriate given the meeting’s subject.')],[M('The joke was unfortunate at the memorial because everyone found it perfectly tactful and comforting.','The joke was appropriate at the memorial because everyone found it tactful and comforting.','A tactful, comforting remark is not unfortunate in that situation.')],[Q('unfortunate.q1','unfortunate.s1','meaning','Why was the festival damage unfortunate?','A storm caused an unlucky loss just before opening.','The organizers planned to destroy the tents.','The festival ended successfully without damage.','The first sense means unlucky or caused by bad luck.'),Q('unfortunate.q2','unfortunate.s2','context','Why was the budget joke unfortunate?','It was tactless during a meeting about layoffs.','It was perfectly suited to a celebration.','It discussed weather at a picnic.','The remark was inappropriate in that setting.'),Q('unfortunate.q3','unfortunate.s1','distinction','Which event is unfortunate in the bad-luck sense?','A lightning strike damages a newly built shelter.','A speaker makes a tactless joke at a funeral.','A manager chooses the wrong word in a meeting.','The lightning strike is an unlucky event.'),Q('unfortunate.q4','unfortunate.s2','word-choice','Choose the phrase about an inappropriate remark.','an unfortunate comment during a solemn ceremony','an unfortunate storm that destroys the tents','an unfortunate lottery loss','The comment is tactless for the situation.')]);
P('unfortunately','From unfortunate + -ly; it can describe an unlucky result or express regret about a fact.',[C('unfortunately.s1','不幸地','The hikers unfortunately chose the flooded trail and had to turn back.','健行者不幸選了淹水的步道，只好折返。','unfortunately + verb / result','Adverb: in a way that brings bad luck or an undesirable result.','Their choice leads to a setback.'),C('unfortunately.s2','遗憾的是','Unfortunately, the archive is closed on Mondays, so we cannot inspect the letters today.','遺憾的是，檔案館週一休館，因此今天無法查看那些信件。','unfortunately, + clause','Sentence adverb: used to express regret about a fact.','The speaker regrets the closure.')],[M('Unfortunately, the archive is open today, so the researchers must cancel their visit.','Fortunately, the archive is open today, so the researchers can make their visit.','An open archive enables the visit; it is fortunate rather than unfortunate.')],[Q('unfortunately.q1','unfortunately.s1','meaning','What happened to the hikers?','They chose a flooded trail and had to turn back.','They reached the summit easily.','They found a dry shortcut.','The adverb describes an unlucky outcome.'),Q('unfortunately.q2','unfortunately.s2','context','Why does the speaker say “Unfortunately” about the archive?','The Monday closure prevents today’s visit.','The archive is open late every Monday.','The letters have already been inspected.','The speaker regrets the fact that it is closed.'),Q('unfortunately.q3','unfortunately.s1','distinction','Which sentence describes an unlucky event?','The boat unfortunately lost power far from shore.','Unfortunately, the office will open at nine.','Unfortunately, the form has a clear title.','The boat’s breakdown is a bad-luck result.'),Q('unfortunately.q4','unfortunately.s2','grammar','What does sentence-initial “Unfortunately,” introduce?','A fact the speaker regrets.','A person’s name.','A direct command to leave.','The adverb comments on the whole clause.')]);
P('unfriendly','From un- “not” + friendly; it describes an unkind person or an unpleasant thing to use.',[C('unfriendly.s1','不友善','The clerk was unfriendly and refused to answer a simple question from the customer.','店員態度不友善，拒絕回答顧客的一個簡單問題。','an unfriendly person / reply / manner','Adjective: not kind or pleasant towards somebody.','The clerk treats the customer coldly.'),C('unfriendly.s2','难以使用','The software has an unfriendly interface that hides basic settings behind several menus.','這款軟體的介面不易使用，把基本設定藏在好幾層選單後面。','an unfriendly interface / environment','Adjective: difficult or unpleasant to use.','The design makes a routine task unnecessarily hard.')],[M('The clerk was unfriendly because she warmly welcomed the customer and patiently answered every question.','The clerk was friendly because she warmly welcomed the customer and patiently answered every question.','A warm welcome and patient help are friendly, not unfriendly.')],[Q('unfriendly.q1','unfriendly.s1','meaning','How did the clerk behave?','Coldly, refusing a simple question.','Warmly, answering every question.','Quietly while closing the shop.','The person sense means not kind or pleasant.'),Q('unfriendly.q2','unfriendly.s2','context','Why was the software interface unfriendly?','It hid basic settings behind several menus.','It made every setting easy to find.','It had no controls at all.','This sense means difficult or unpleasant to use.'),Q('unfriendly.q3','unfriendly.s1','distinction','Which is an unfriendly response?','A cashier snaps at a customer asking for help.','A cashier patiently explains the refund policy.','A cashier greets a customer with a smile.','The first response is unkind.'),Q('unfriendly.q4','unfriendly.s2','word-choice','Choose the phrase about poor usability.','an unfriendly website form with confusing navigation','an unfriendly neighbour who refuses to greet anyone','an unfriendly guest who insults the host','The website phrase uses unfriendly for difficult to use.')]);
P('unfulfilling','From un- “not” + fulfilling, present participle of fulfil, “satisfy.”',[C('unfulfilling.s1','缺乏满足感','Although the job paid well, repetitive data entry made it unfulfilling for the analyst.','雖然薪酬不錯，重複輸入資料仍讓分析師覺得工作缺乏成就感。','an unfulfilling job / experience','Adjective: not providing personal satisfaction or a sense of achievement.','The repetitive task leaves the analyst dissatisfied.')],[M('The work was unfulfilling because it gave the analyst deep satisfaction and a strong sense of achievement.','The work was fulfilling because it gave the analyst deep satisfaction and a strong sense of achievement.','Satisfaction and achievement make work fulfilling, not unfulfilling.')],[Q('unfulfilling.q1','unfulfilling.s1','meaning','Why did the analyst find the job unfulfilling?','Repetitive work gave little satisfaction.','The work provided deep achievement every day.','The salary was unpaid.','Unfulfilling means not personally satisfying.'),Q('unfulfilling.q2','unfulfilling.s1','context','Which experience is unfulfilling?','A project uses someone’s skills but produces no sense of purpose.','A volunteer role makes a clear difference to families.','A course teaches a useful skill the student enjoys.','The first provides no personal satisfaction.'),Q('unfulfilling.q3','unfulfilling.s1','distinction','What is the opposite of an unfulfilling job?','Work that feels meaningful and satisfying.','Work that feels empty and repetitive.','Work with no completed tasks.','Meaning and satisfaction make work fulfilling.'),Q('unfulfilling.q4','unfulfilling.s1','word-choice','Choose the natural phrase.','an unfulfilling routine that left her bored','an unfulfilling project that gave lasting satisfaction','an unfulfilling job she found deeply meaningful','The routine leaves her without satisfaction.')]);
P('ungainly','From un- “not” + gainly, an older word for “suitable or graceful.”',[C('ungainly.s1','笨拙外形或动作','The young giraffe moved with ungainly steps as it learned to control its long legs.','年輕的長頸鹿還在學著控制長腿，走起路來笨拙。','an ungainly movement / shape / figure','Adjective: clumsy or ungraceful in movement or shape.','Its steps lack coordination and grace.')],[M('The dancer’s ungainly movement was smooth, balanced, and admired for its grace.','The dancer’s graceful movement was smooth, balanced, and admired for its grace.','Smooth, balanced, admired movement is graceful, not ungainly.')],[Q('ungainly.q1','ungainly.s1','meaning','How did the young giraffe move?','Clumsily while learning to control its legs.','Smoothly with perfect coordination.','It remained completely still.','Ungainly means clumsy or ungraceful.'),Q('ungainly.q2','ungainly.s1','context','Which object has an ungainly shape?','A bulky chair with awkward proportions.','A slim chair designed with elegant curves.','A small plain cup with a balanced shape.','The bulky chair looks awkward.'),Q('ungainly.q3','ungainly.s1','distinction','Which movement is ungainly?','A toddler stumbles while trying to carry a large box.','A gymnast lands steadily after a practiced turn.','A dancer glides smoothly across the floor.','Stumbling with a heavy box is awkward.'),Q('ungainly.q4','ungainly.s1','word-choice','Choose the accurate phrase.','an ungainly machine that is awkward to steer','an ungainly glide praised for perfect elegance','an ungainly shape with graceful proportions','The machine is awkward to control.')]);
P('unhappy','From un- “not” + happy; it can mean displeased or slightly worried, and can describe something causing distress.',[C('unhappy.s1','不高兴或担忧','Nora was unhappy about the sudden change to her work schedule.','諾拉對工作時間突然改變感到不滿。','be unhappy about / with + situation','Adjective: not pleased or content, sometimes worried.','The schedule change displeases her.'),C('unhappy.s2','令人难受','The film tells an unhappy story about a family separated by war.','這部電影講述一家人因戰爭分離的悲傷故事。','an unhappy ending / situation / story','Adjective: causing distress or suffering.','The story makes viewers feel sad.')],[M('Nora was unhappy about the schedule because it perfectly suited her needs and caused no concern.','Nora was happy with the schedule because it perfectly suited her needs and caused no concern.','A schedule that suits her perfectly makes her happy rather than unhappy.')],[Q('unhappy.q1','unhappy.s1','meaning','Why was Nora unhappy?','The sudden schedule change displeased her.','The schedule perfectly suited her needs.','She had no change to her work.','This sense means not pleased or content.'),Q('unhappy.q2','unhappy.s2','context','What kind of story is the film?','A sad story about a family separated by war.','A cheerful comedy about a reunion.','A neutral manual about scheduling.','The story causes distress.'),Q('unhappy.q3','unhappy.s1','distinction','Which sentence shows dissatisfaction?','He was unhappy with the noisy room.','He was delighted with the quiet room.','He was worried about a possible storm.','The first explicitly signals displeasure.'),Q('unhappy.q4','unhappy.s2','word-choice','Choose the phrase describing something that causes sadness.','an unhappy ending to the family’s journey','an unhappy guest who dislikes the meal','an unhappy worker who wants a new schedule','The ending itself causes distress.')]);
P('unharmed','From un- “not” + harmed, past participle of harm.',[C('unharmed.s1','未受伤','The passengers climbed out of the bus unharmed after it slid into a shallow ditch.','公車滑進淺溝後，乘客都平安無傷地爬了出來。','escape / remain / return unharmed','Adjective: not hurt or damaged, especially after danger.','No passenger suffered an injury in the accident.')],[M('The passengers were unharmed, but several were taken to hospital with serious injuries.','The passengers were injured, and several were taken to hospital with serious injuries.','People with serious injuries are not unharmed.')],[Q('unharmed.q1','unharmed.s1','meaning','What happened to the passengers?','They escaped without injury.','They suffered serious injuries.','They remained trapped in the bus.','Unharmed means not hurt or damaged.'),Q('unharmed.q2','unharmed.s1','context','Which animal returned unharmed?','A rescued dog had no cuts or other injuries.','A dog returned with a broken leg.','A damaged truck was towed away.','The dog was not physically hurt.'),Q('unharmed.q3','unharmed.s1','distinction','Which person is unharmed after a fall?','Someone checked by doctors who has no injury.','Someone with a fractured arm.','Someone whose clothes are torn and skin is cut.','No injury means the person is unharmed.'),Q('unharmed.q4','unharmed.s1','word-choice','Choose the natural report.','The hikers were found alive and unharmed.','The hikers were unharmed despite their confirmed broken bones.','The hikers were unharmed after suffering several injuries.','The report says they had no injuries.')]);
P('unhealthy','From un- “not” + healthy; it describes poor health or something harmful to health or sound judgment.',[C('unhealthy.s1','健康状况','The doctor advised him to reduce his unhealthy reliance on sugary drinks.','醫生建議他減少對含糖飲料的不健康依賴。','an unhealthy diet / habit / condition','Adjective: not well or likely to damage physical health.','Frequent sugary drinks may harm his health.'),C('unhealthy.s1','不良影响','The group developed an unhealthy dependence on one supplier and had no backup.','這個團體對單一供應商產生不健康的依賴，沒有備用方案。','an unhealthy relationship / dependence / atmosphere','Adjective: damaging to sound judgment or normal relationships.','The dependence creates a risky imbalance.')],[M('His unhealthy habit improved his health because he replaced water with large amounts of sugary drinks.','His unhealthy habit harmed his health because he replaced water with large amounts of sugary drinks.','Replacing water with excess sugary drinks can damage health.')],[Q('unhealthy.q1','unhealthy.s1','meaning','Why did the doctor call the drinking habit unhealthy?','Frequent sugary drinks could damage his physical health.','The drinks contained no sugar and improved his health.','He drank enough water every day.','The adjective can mean harmful to physical health.'),Q('unhealthy.q2','unhealthy.s1','context','Why was dependence on one supplier unhealthy?','It created a risky relationship with no backup.','It gave the group several reliable suppliers.','It improved the group’s independence.','This sense can describe a damaging dependence.'),Q('unhealthy.q3','unhealthy.s1','distinction','Which use concerns physical health?','an unhealthy diet high in salt and sugar','an unhealthy dependence on one manager','an unhealthy atmosphere of control','The diet may damage the body.'),Q('unhealthy.q4','unhealthy.s1','word-choice','Choose the use about a damaging relationship.','an unhealthy dependence that prevents independent decisions','an unhealthy meal containing excess fat','an unhealthy fever requiring a doctor','The dependence impairs sound judgment and autonomy.')]);
P('unheard of','From un- “not” + heard + of; the phrase means never previously known or experienced.',[C('unheard of.s1','前所未闻','A two-week heat wave in early spring was unheard of in the region’s recorded climate history.','在當地有紀錄的氣候史上，早春出現兩週熱浪是前所未聞的。','be unheard of; it is unheard of for + event','Adjective phrase: never known or talked about because nothing similar has happened.','No comparable heat wave appears in the historical record.')],[M('A two-week early-spring heat wave was unheard of, although it happened every year for centuries.','A two-week early-spring heat wave was familiar, because it happened every year for centuries.','An event repeated for centuries is known, not unheard of.')],[Q('unheard of.q1','unheard of.s1','meaning','Why was the heat wave unheard of?','No similar event appeared in the region’s recorded history.','It happened every spring for centuries.','The region had no climate records.','The phrase means never previously known or experienced.'),Q('unheard of.q2','unheard of.s1','context','Which event would be unheard of?','A village receives snow in midsummer for the first time in its records.','A town holds its annual summer fair.','A regular train arrives at its usual time.','The midsummer snow is unprecedented.'),Q('unheard of.q3','unheard of.s1','distinction','What does “It is unheard of for the lake to freeze in July” mean?','That has never been known to happen there.','The lake freezes every July.','People have not listened to the lake.','The idiom describes an unprecedented event.'),Q('unheard of.q4','unheard of.s1','grammar','Choose the idiomatic sentence.','Such a delay is unheard of here.','Such a delay is unheard here of it.','Such a delay is unheard-ofing here.','The fixed phrase is unheard of, usually after be.')]);
P('unhindered','From un- “not” + hindered, past participle of hinder.',[C('unhindered.s1','不受阻碍','With the fallen branches cleared, emergency vehicles moved unhindered along the road.','倒下的樹枝清除後，救援車輛在道路上暢行無阻。','move / proceed / continue unhindered','Adjective: able to continue without obstacles or interference.','Nothing blocks or slows the vehicles.')],[M('Emergency vehicles moved unhindered because fallen branches completely blocked the road.','Emergency vehicles were hindered because fallen branches completely blocked the road.','A blocked road obstructs vehicles, so their movement is hindered.')],[Q('unhindered.q1','unhindered.s1','meaning','How did the emergency vehicles move?','They continued without obstacles after the road was cleared.','They were trapped behind fallen branches.','They stopped because the road was closed.','Unhindered means able to proceed without obstruction.'),Q('unhindered.q2','unhindered.s1','context','Which project proceeded unhindered?','A permit arrived on time and no obstacle delayed the work.','A missing permit stopped the crew for weeks.','A blocked road prevented delivery.','No obstacle interfered with the project.'),Q('unhindered.q3','unhindered.s1','distinction','Which path allows unhindered movement?','A clear corridor with no barriers.','A passage blocked by fallen timber.','A door locked against all entry.','The clear corridor has no obstruction.'),Q('unhindered.q4','unhindered.s1','word-choice','Choose the accurate sentence.','The rescue team worked unhindered after power was restored.','The rescue team worked unhindered while every tool was locked away.','The rescue team was unhindered by obstacles that stopped all progress.','Restored power allowed the team to work without interference.')]);
})();
